INSERT INTO heritage_site (id, name, city, era, type, type_desc, dynasty, summary, image, detail_json) VALUES
('yangshao', '仰韶村遗址', '三门峡', '仰韶', '古建筑', '聚落遗址', '新石器时代中晚期（约7000—5000年前）', '中国现代考古学的发源地，“仰韶文化”的命名地', 'yangshao.jpg', '{"id":"yangshao","name":"仰韶村遗址","city":"三门峡","era":"仰韶","type":"古建筑","typeDesc":"聚落遗址","dynasty":"新石器时代中晚期（约7000—5000年前）","cover":"🏺","image":"yangshao.jpg","summary":"中国现代考古学的发源地，“仰韶文化”的命名地","intro":"仰韶村遗址位于三门峡市渑池县仰韶镇，是黄河流域新石器时代最具代表性的文化遗存之一。1921年，瑞典地质学家安特生经中国政府批准在此进行首次考古发掘，发现了以彩陶为典型特征的史前文化，由此确立了中国第一个考古学文化——仰韶文化。遗址面积约30万平方米，文化层厚达数米，出土了大量红陶、彩陶及磨制石器，是探索中华文明起源的关键遗址。","archaeology":"1921年安特生首次发掘出土大量彩陶与石器；1951年、1980—1981年中国科学院考古研究所等单位多次复查与试掘，确认遗址包含仰韶文化早中晚期及龙山文化等连续地层；2000—2001年再次发掘，出土陶器、石器、骨器、蚌器等万余件，并发现房址、灰坑、墓葬等遗迹。2021年仰韶文化发现100周年之际，遗址博物馆建成开放。","relics":[{"name":"小口尖底瓶","desc":"仰韶文化最具代表性的汲水器，小口、深腹、尖底，腹侧有双耳，入水后自动倾倒汲水，体现史前先民的力学智慧。"},{"name":"彩陶花瓣纹盆","desc":"泥质红陶，口沿与腹部以黑彩绘出花瓣纹与几何纹，是庙底沟类型彩陶的典型装饰母题。"}],"events":[{"time":"1921年","title":"中国现代考古学从这里起步","desc":"安特生主持的仰韶村发掘，是中国第一次以科学方法开展的史前考古发掘，成为新石器时代考古的开端。"},{"time":"1923年","title":"《中华远古之文化》发表","desc":"安特生发表发掘报告，正式提出“仰韶文化”命名，奠定中国新石器时代研究基础。"},{"time":"1961年","title":"首批全国重点文物保护单位","desc":"仰韶村遗址被国务院公布为第一批全国重点文物保护单位。"}],"poems":[{"title":"考古学界评价","author":"学界共识","content":"中国现代考古学从这里起步，仰韶文化是华夏文明的第一缕曙光。"}],"tourism":{"address":"三门峡市渑池县仰韶镇仰韶村","openTime":"仰韶文化博物馆：周二至周日开放，具体以景区公告为准","ticket":"以景区公告为准","tips":"建议与仰韶文化博物馆、渑池县城的仰韶文化产业园联游，可近距离观摩彩陶制作体验。"},"keywords":["彩陶","安特生","考古学","渑池","新石器"]}'),
('xipo', '西坡遗址', '三门峡', '仰韶', '古建筑', '大型公共建筑基址', '仰韶文化中期（约6000年前）', '出土“华夏第一宫殿”式大型房址，仰韶中期权力中心', 'xipo.jpg', '{"id":"xipo","name":"西坡遗址","city":"三门峡","era":"仰韶","type":"古建筑","typeDesc":"大型公共建筑基址","dynasty":"仰韶文化中期（约6000年前）","cover":"🏛️","image":"xipo.jpg","summary":"出土“华夏第一宫殿”式大型房址，仰韶中期权力中心","intro":"西坡遗址位于三门峡灵宝市阳平镇，地处铸鼎原上，是仰韶文化中期核心聚落之一。遗址中发掘出多座规模宏大的半地穴式建筑，其中F105、F106两座大型房址面积分别达516平方米和240平方米，以木骨泥墙、回廊式结构建造，被学界称为“华夏第一宫殿”，展现出5000多年前黄河先民惊人的社会组织与建筑能力。","archaeology":"2000—2006年，中国社会科学院考古研究所与河南省文物考古研究所联合发掘，发现大型半地穴式房屋、蓄水池、壕沟及墓地等遗迹。F105房址室内面积约516平方米，结构完整、工艺精湛，出土大量陶器、石器、骨器与装饰品。西坡遗址与灵宝铸鼎原黄帝铸鼎传说区域相邻，为探索中华文明起源提供了重要实物证据。","relics":[{"name":"玉钺","desc":"西坡遗址大型房址与墓葬出土，玉质温润、刃部无使用痕迹，是距今五千余年的权力与身份象征物。"},{"name":"大口深腹缸","desc":"庙底沟类型常见大型陶器，器壁厚重，多用于储粮或酿酒，反映仰韶中晚期的定居农业规模。"}],"events":[{"time":"2000—2006年","title":"系统性考古发掘","desc":"连续多年大规模发掘，确认西坡遗址为仰韶中期区域性中心聚落。"},{"time":"2006年","title":"入选全国重点文物保护单位","desc":"西坡遗址被国务院公布为第六批全国重点文物保护单位。"}],"poems":[{"title":"《史记·封禅书》","author":"司马迁","content":"黄帝采首山铜，铸鼎于荆山下。鼎既成，有龙垂胡髯下迎黄帝。"}],"tourism":{"address":"三门峡灵宝市阳平镇，铸鼎原景区内","openTime":"以景区公告为准","ticket":"以景区公告为准","tips":"可与荆山黄帝铸鼎原、函谷关串联为三门峡人文一日游线路。"},"keywords":["华夏第一宫殿","铸鼎原","黄帝传说","灵宝","大型房址"]}'),
('guoguo', '虢国墓地', '三门峡', '周', '墓葬群', '西周虢国国君及贵族墓地', '西周—春秋早期', '出土“中华第一铁剑”的西周诸侯国墓地', 'guoguo.jpg', '{"id":"guoguo","name":"虢国墓地","city":"三门峡","era":"周","type":"墓葬群","typeDesc":"西周虢国国君及贵族墓地","dynasty":"西周—春秋早期","cover":"🗡️","image":"guoguo.jpg","summary":"出土“中华第一铁剑”的西周诸侯国墓地","intro":"虢国墓地位于三门峡市区上村岭，是西周晚期至春秋早期虢国国君及高级贵族的公墓区。“假虞灭虢”“唇亡齿寒”等典故皆与虢国相关。墓地规模宏大、等级分明，出土青铜礼器、玉器、车马器数以万计，其中虢季墓出土的玉柄铁剑被誉为“中华第一铁剑”，将中国人工冶铁史提早到西周晚期。","archaeology":"1956—1957年黄河水库考古工作队发现并发掘上村岭虢国墓地，发掘墓葬234座；1990—1999年第二次大规模发掘，发现虢国国君虢季墓（M2001）、虢仲墓（M2009）等大型墓葬，出土青铜器、玉器两万余件。虢国博物馆建在遗址之上，为“中国20世纪100项考古大发现”之一。","relics":[{"name":"玉柄铁剑","desc":"以玉为柄、铜芯包铁的复合材质兵器，是中国境内目前所见最早的人工冶铁制品之一，被誉为\\"中华第一剑\\"。"},{"name":"七璜联珠组玉佩","desc":"七件玉璜与玛瑙珠串联而成的组佩，出土于国君夫人墓，是西周礼玉制度的典型代表。"}],"events":[{"time":"1956年","title":"上村岭虢国墓地发现","desc":"配合三门峡水利工程建设，考古队发现并发掘虢国墓地。"},{"time":"1990年","title":"虢季、虢仲大墓出土","desc":"两座国君级大墓出土大量青铜重器与玉器，震惊考古界。"},{"time":"1996年","title":"入选全国重点文物保护单位","desc":"虢国墓地与虢国车马坑遗址被国务院公布为第四批全国重点文物保护单位。"}],"poems":[{"title":"《左传·僖公五年》","author":"左丘明","content":"虢，虞之表也。虢亡，虞必从之……谚所谓“辅车相依，唇亡齿寒”者，其虞虢之谓也。"}],"tourism":{"address":"三门峡市湖滨区六峰北路虢国博物馆","openTime":"周二至周日，具体以博物馆公告为准","ticket":"以博物馆公告为准","tips":"虢季墓原址、车马坑陈列气势震撼；玉柄铁剑与缀玉面罩为镇馆之宝。"},"keywords":["唇亡齿寒","中华第一铁剑","虢季墓","三门峡","玉器"]}'),
('hanguguan', '函谷关遗址', '三门峡', '汉唐', '古建筑', '关隘建筑与遗址', '战国始建，汉代鼎盛', '“一夫当关，万夫莫开”的雄关，老子著《道德经》之地', 'hanguguan.jpg', '{"id":"hanguguan","name":"函谷关遗址","city":"三门峡","era":"汉唐","type":"古建筑","typeDesc":"关隘建筑与遗址","dynasty":"战国始建，汉代鼎盛","cover":"🏔️","image":"hanguguan.jpg","summary":"“一夫当关，万夫莫开”的雄关，老子著《道德经》之地","intro":"函谷关位于三门峡灵宝市北15公里，因关在谷中、深险如函而得名，是古代连接关中与中原的咽喉要道。战国时秦国置关，汉代犹盛，历代为兵家必争之地。相传老子西出函谷关，应关令尹喜之请著《道德经》五千言，使此关成为中国哲学史上的圣地。","archaeology":"考古调查与发掘确认关城遗址范围，发现城墙基址、古道遗迹与汉代仓储建筑遗存；遗址区还分布太初宫（老子著经处传说建筑）等古迹。函谷关古文化旅游区以雄关、古道、太初宫为主体，再现“紫气东来”的历史意象。","relics":[{"name":"函谷关关城遗存","desc":"战国至汉代关隘遗存，地处崤函古道咽喉，是古代中原通往关中的军事要冲。"},{"name":"战国铜箭镞与兵器","desc":"关隘周边出土的箭镞、戈、矛等兵器，印证了函谷关作为兵家必争之地的历史。"}],"events":[{"time":"战国—汉代","title":"关城营建与戍守","desc":"函谷关长期作为关中门户，秦、汉均在要害时期强化关防。"},{"time":"先秦","title":"老子著《道德经》","desc":"相传老子骑青牛西行至此，关令尹喜留之，遂著《道德经》五千言。"}],"poems":[{"title":"《函谷关》","author":"胡宿（宋）","content":"天开函谷壮关中，万古惊尘向此空。"}],"tourism":{"address":"三门峡灵宝市函谷关镇函谷关历史文化旅游区","openTime":"具体以景区公告为准","ticket":"以景区公告为准","tips":"鸡鸣台、太初宫、老子像为打卡点；可结合西坡遗址、黄帝铸鼎原安排线路。"},"keywords":["老子","道德经","一夫当关","灵宝","关隘"]}'),
('erlituo', '二里头遗址', '洛阳', '夏商', '都城遗址', '夏代中晚期都城', '夏代中晚期（约3800—3500年前）', '“最早的中国”——夏都斟鄩，中华文明总进程的核心与引领者', 'erlituo.jpg', '{"id":"erlituo","name":"二里头遗址","city":"洛阳","era":"夏商","type":"都城遗址","typeDesc":"夏代中晚期都城","dynasty":"夏代中晚期（约3800—3500年前）","cover":"👑","image":"erlituo.jpg","summary":"“最早的中国”——夏都斟鄩，中华文明总进程的核心与引领者","intro":"二里头遗址位于洛阳市偃师区，被学界普遍认定为夏代中晚期都城“斟鄩”，距今约3800—3500年，是经考古证实的最早的中国王朝都城遗址。遗址内发现中国最早的宫城、城市主干道网、青铜礼器群和绿松石龙形器，标志着中国由“古国”迈入“王国”时代，是探索夏文化、研究中华文明起源的核心遗址。","archaeology":"1959年徐旭生先生踏查发现后持续发掘至今。宫城内发现多座大型夯土宫殿基址，二里头“网格化”都邑布局严谨；出土青铜爵、青铜鼎、镶嵌绿松石兽面纹铜牌饰、绿松石龙形器等顶级礼器，以及中国最早的宫城和官营手工业作坊区。2019年二里头夏都遗址博物馆建成开放。","relics":[{"name":"乳钉纹铜爵","desc":"中国目前发现最早的青铜容器之一，器身细长、流尾上扬，腰部饰乳钉纹，代表早期青铜铸造的最高水平。"},{"name":"镶嵌绿松石铜牌饰","desc":"以数百片绿松石镶嵌成兽面纹，工艺精湛，是中国最早的成熟镶嵌铜器之一。"},{"name":"绿松石龙形器","desc":"大型绿松石片组成的龙形图案，长约七十厘米，被誉为\\"华夏第一龙\\"，与早期礼制密切相关。"}],"events":[{"time":"1959年","title":"徐旭生踏查发现","desc":"著名考古学家徐旭生依据文献线索到偃师二里头一带调查，揭开夏都探源序幕。"},{"time":"1988年","title":"入选全国重点文物保护单位","desc":"二里头遗址被国务院公布为第三批全国重点文物保护单位。"},{"time":"2019年","title":"二里头夏都遗址博物馆开馆","desc":"博物馆正式开放，“最早的中国”面向公众系统呈现。"}],"poems":[{"title":"《竹书纪年》","author":"佚名（战国史书）","content":"太康居斟鄩，羿亦居之，桀又居之。"}],"tourism":{"address":"洛阳市偃师区翟镇镇二里头夏都遗址博物馆","openTime":"周二至周日，具体以博物馆公告为准","ticket":"免费预约参观，以博物馆公告为准","tips":"绿松石龙形器、乳钉纹青铜爵为必看展品；馆内二里头“井”字街复原值得体验。"},"keywords":["最早的中国","夏都斟鄩","绿松石龙","偃师","青铜爵"]}'),
('hanweigucheng', '汉魏洛阳故城', '洛阳', '汉唐', '都城遗址', '东汉至北魏都城遗址', '东汉、曹魏、西晋、北魏（公元25—534年）', '“天下之中”，汉魏时期世界级大都市与丝绸之路东方起点', 'hanweigucheng.jpg', '{"id":"hanweigucheng","name":"汉魏洛阳故城","city":"洛阳","era":"汉唐","type":"都城遗址","typeDesc":"东汉至北魏都城遗址","dynasty":"东汉、曹魏、西晋、北魏（公元25—534年）","cover":"🏟️","image":"hanweigucheng.jpg","summary":"“天下之中”，汉魏时期世界级大都市与丝绸之路东方起点","intro":"汉魏洛阳故城位于洛阳市洛龙区与偃师区交界，先后为东汉、曹魏、西晋、北魏四朝都城，历时五百余年。北魏时期城郭人口逾百万，是当时世界上规模最大的城市之一；城南辟雍、太学、明堂、灵台等礼制建筑遗迹犹存，太学遗址出土《熹平石经》残石，见证中国古代教育史。","archaeology":"1962年起中国社会科学院考古研究所持续发掘，确认宫城、永宁寺塔基、铜驼大街、灵台、太学等重要遗址。永宁寺木塔高约136米，为古代世界最高木构建筑之一，其塔基出土大量北魏泥塑残像，被誉为“东方蒙娜丽莎”。1988年列为全国重点文物保护单位，2021年入选中国“百年百大考古发现”。","relics":[{"name":"太极殿基址","desc":"汉魏洛阳城宫城正殿基址，规模宏大，是中国古代都城\\"居中\\"正殿布局的重要源头。"},{"name":"永宁寺塔基","desc":"北魏皇家寺院永宁寺木塔的夯土塔基，据载塔高百丈，是北魏洛阳城的地标性建筑遗存。"},{"name":"熹平石经残石","desc":"东汉刊刻的儒家经典石经残块，是中国最早的官定儒家经典刻石，兼具文献与书法价值。"}],"events":[{"time":"东汉至北魏","title":"四朝为都","desc":"汉魏洛阳故城作为四朝都城，是中华文明在汉唐之间的核心政治文化中心。"},{"time":"1962年","title":"科学考古发掘启动","desc":"考古研究所对故城进行全面勘查与重点发掘，廓清城址布局。"}],"poems":[{"title":"《芙蓉楼送辛渐》","author":"王昌龄","content":"寒雨连江夜入吴，平明送客楚山孤。洛阳亲友如相问，一片冰心在玉壶。"}],"tourism":{"address":"洛阳市洛龙区佃庄镇汉魏洛阳故城遗址（洛偃快速通道附近）","openTime":"遗址公园以景区公告为准","ticket":"以景区公告为准","tips":"永宁寺塔基、太极殿遗址区最具现场感；可与二里头遗址博物馆联线参观。"},"keywords":["东汉","北魏","永宁寺塔","丝绸之路","洛阳"]}'),
('suitangluoyang', '隋唐洛阳城', '洛阳', '汉唐', '都城遗址', '隋唐都城遗址', '隋唐时期（公元605—907年）', '隋唐“神都”，应天门、明堂天堂见证盛唐气象', 'suitangluoyang.jpg', '{"id":"suitangluoyang","name":"隋唐洛阳城","city":"洛阳","era":"汉唐","type":"都城遗址","typeDesc":"隋唐都城遗址","dynasty":"隋唐时期（公元605—907年）","cover":"🏛️","image":"suitangluoyang.jpg","summary":"隋唐“神都”，应天门、明堂天堂见证盛唐气象","intro":"隋唐洛阳城位于今洛阳市区，隋炀帝始建东都，武则天时期称“神都”，是天平盛世的标志性都城。城址由宫城、皇城、外郭城三重城垣构成，中轴线“七天建筑”以天阙（应天门）、天宫（明堂）、天堂等命名，气势恢宏。大运河与丝绸之路在此交汇，是当时国际性大都市。","archaeology":"20世纪50年代以来持续考古，确认定鼎门、应天门、明堂、天堂、九洲池等重要遗址。应天门为隋唐宫城正门，门址东西宽达137米，规模为国内之最；明堂天堂遗址经保护性展示，复原了武周时期宏伟建筑。2014年隋唐洛阳城定鼎门遗址作为大运河遗产点列入世界遗产。","relics":[{"name":"明堂、天堂遗址","desc":"武则天时期营建的礼制与佛教建筑基址，规模宏大，是隋唐洛阳城的核心轴线节点。"},{"name":"含嘉仓仓窖","desc":"隋唐时期大型官仓遗存，窖穴密集、储粮巨万，见证大运河漕运与东都粮食储备体系。"},{"name":"唐三彩器物","desc":"隋唐洛阳城及窑址出土的三彩俑、三彩器，釉色斑斓，是唐代陶瓷与丧葬文化的代表。"}],"events":[{"time":"公元605年","title":"隋炀帝营建东都","desc":"宇文恺主持营建洛阳城，开创都城中轴线设计新格局。"},{"time":"武则天时期","title":"神都鼎盛","desc":"武则天改洛阳为“神都”，修建明堂、天堂，洛阳成为全国政治中心。"}],"poems":[{"title":"《春兴》","author":"武元衡（唐）","content":"杨柳阴阴细雨晴，残花落尽见流莺。春风一夜吹乡梦，又逐春风到洛城。"}],"tourism":{"address":"洛阳市老城区、西工区隋唐洛阳城国家遗址公园（应天门、明堂天堂、九洲池）","openTime":"具体以景区公告为准","ticket":"以景区公告为准","tips":"应天门夜晚灯光秀与《唐宫乐宴》演出极具盛唐沉浸感，建议傍晚入园。"},"keywords":["武则天","神都","应天门","明堂天堂","大运河"]}'),
('longmen', '龙门石窟', '洛阳', '汉唐', '古建筑', '石窟寺建筑群', '北魏至唐（公元493年始凿）', '世界文化遗产，中国石窟艺术的巅峰之作', 'longmen.jpg', '{"id":"longmen","name":"龙门石窟","city":"洛阳","era":"汉唐","type":"古建筑","typeDesc":"石窟寺建筑群","dynasty":"北魏至唐（公元493年始凿）","cover":"🪨","image":"longmen.jpg","summary":"世界文化遗产，中国石窟艺术的巅峰之作","intro":"龙门石窟位于洛阳市南郊伊河两岸的龙门山与香山之上，始凿于北魏孝文帝迁都洛阳（493年）之际，历经东魏至唐四百余年营造，现存窟龛2345个、造像近11万尊，是世界上营造时间最长、规模最大的石窟群之一。奉先寺卢舍那大佛高17.14米，相传以武则天为原型，面容庄严慈祥，被誉为“东方最美微笑”。","archaeology":"龙门石窟为皇家石窟造像艺术的代表，北魏古阳洞、宾阳中洞，唐代潜溪寺、奉先寺等均为重要遗存；现存碑刻题记2860余品，其中“龙门二十品”为魏碑书法经典。2000年龙门石窟列入《世界遗产名录》。白居易晚年居香山，号“香山居士”，与龙门渊源深厚。","relics":[{"name":"卢舍那大佛","desc":"奉先寺主尊，通高逾十七米，面容庄严慈和，代表唐代石雕艺术的最高成就。"},{"name":"宾阳中洞造像","desc":"北魏时期开凿的皇家洞窟，造像衣纹流畅、秀骨清像，体现北魏石窟艺术的典型风格。"}],"events":[{"time":"公元493年","title":"北魏开凿","desc":"孝文帝迁都洛阳后，龙门石窟开凿工程启动。"},{"time":"唐高宗至武则天时期","title":"奉先寺大像龛完工","desc":"卢舍那大佛及群像雕成，代表唐代石窟艺术最高成就。"},{"time":"2000年","title":"列入世界遗产名录","desc":"龙门石窟被联合国教科文组织列入《世界遗产名录》。"}],"poems":[{"title":"《修香山寺记》","author":"白居易","content":"洛都四郊，山水之胜，龙门首焉。"}],"tourism":{"address":"洛阳市洛龙区龙门中街龙门石窟景区","openTime":"具体以景区公告为准","ticket":"以景区公告为准","tips":"建议上午游览西山石窟，过漫水桥登香山寺；夜游龙门灯光下的卢舍那大佛别有气象。"},"keywords":["卢舍那大佛","世界文化遗产","奉先寺","白居易","石窟艺术"]}'),
('baimasi', '白马寺', '洛阳', '汉唐', '古建筑', '佛教寺院建筑', '东汉始建（公元68年）', '中国第一古刹，佛教传入中国后兴建的第一座官办寺院', 'baimasi.jpg', '{"id":"baimasi","name":"白马寺","city":"洛阳","era":"汉唐","type":"古建筑","typeDesc":"佛教寺院建筑","dynasty":"东汉始建（公元68年）","cover":"🛕","image":"baimasi.jpg","summary":"中国第一古刹，佛教传入中国后兴建的第一座官办寺院","intro":"白马寺位于洛阳市东12公里，始建于东汉永平十一年（公元68年），是佛教传入中国后兴建的第一座官办寺院，有“释源”“祖庭”之称。相传汉明帝夜梦金人，遣使西行求法，以白马驮载佛经、佛像返回洛阳，遂建寺以“白马”命名。寺内保存有齐云塔、清凉台、大雄殿等历代建筑与元代夹纻干漆造像。","archaeology":"白马寺东南侧的金村大墓与汉魏洛阳故城相邻，寺址历经多次修缮；1961年被国务院公布为第一批全国重点文物保护单位。寺内现存宋代齐云塔、元代“夹纻干漆十八罗汉”等珍贵文物，为研究中国早期佛教建筑与造像艺术的重要实物。","relics":[{"name":"齐云塔","desc":"金代重建的方形密檐式砖塔，为中国第一古刹白马寺的标志性建筑，塔身砖雕精美。"},{"name":"元代夹纻干漆造像","desc":"采用夹纻干漆工艺塑造的罗汉像，质地轻坚、保存完好，为元代造像艺术珍品。"}],"events":[{"time":"公元68年","title":"建寺译经","desc":"白马寺建成，摄摩腾、竺法兰在此译出《四十二章经》，为中国译经之始。"},{"time":"1961年","title":"入选全国重点文物保护单位","desc":"白马寺被国务院公布为第一批全国重点文物保护单位。"}],"poems":[{"title":"《宿白马寺》","author":"张继（唐）","content":"白马驮经事已空，断碑残刹见遗踪。萧萧茅屋秋风起，一夜雨声羁思浓。"}],"tourism":{"address":"洛阳市洛龙区白马寺镇（洛白路6号）","openTime":"具体以景区公告为准","ticket":"以景区公告为准","tips":"寺内国际佛殿苑（泰国、印度、缅甸风格佛殿）为一寺容三国特色的独特景观。"},"keywords":["释源祖庭","第一古刹","白马驮经","洛阳","佛教"]}'),
('yuancheng', '原城遗址（庙街遗址）', '济源', '龙山', '都城遗址', '文献记载夏代“原”地', '龙山文化—二里头文化至战国', '文献载夏王居“原”，考古文化层延续至战国', 'yuancheng.jpg', '{"id":"yuancheng","name":"原城遗址（庙街遗址）","city":"济源","era":"龙山","type":"都城遗址","typeDesc":"文献记载夏代“原”地","dynasty":"龙山文化—二里头文化至战国","cover":"🏯","image":"yuancheng.jpg","summary":"文献载夏王居“原”，考古文化层延续至战国","intro":"原城遗址位于济源市区西北庙街村一带，地处济水上游、黄河北岸文化区。《竹书纪年》等文献有“少康迁原”“帝杼居原”的记载，地方资料也将其与夏代政治活动联系起来。遗址包含龙山、二里头、商、周乃至战国时期文化层，但目前尚未发现能够直接证明夏代都城性质的宫殿、文字或完整城垣。","archaeology":"1959年文物工作者曾对遗址进行试掘，遗址面积约63万至75万平方米，采集和出土黑陶、灰陶、鼎、罐、盆等遗物，确认其文化序列延续较长。1963年被公布为河南省文物保护单位，现结合遗址保护推进原城遗址考古公园建设。夏都性质仍属于文献记载与考古探索互证阶段。","relics":[{"name":"龙山文化黑陶杯","desc":"胎壁较薄、色泽乌黑，是龙山文化系统常见器物，可用于研究济源地区史前陶器工艺。"},{"name":"二里头文化陶鼎","desc":"鼎足与口沿具有二里头文化特征，反映原城遗址与夏文化核心区之间的文化联系。"}],"events":[{"time":"先秦文献","title":"夏王居原的记载","desc":"《竹书纪年》等文献记载夏代帝王曾居“原”，成为济源历史地望的重要线索。"},{"time":"1963年","title":"列入河南省文物保护单位","desc":"原城遗址被公布为河南省文物保护单位，遗址保护和考古研究持续推进。"}],"poems":[{"title":"考古说明","author":"文博研究","content":"原城是探索夏代都邑的重要线索，但仍需宫殿、城垣和文字等关键证据形成闭环。"}],"tourism":{"address":"济源市北海街道庙街村一带","openTime":"遗址以现场保护为主，参观以当地公告为准","ticket":"以现场公告为准","tips":"可与济渎庙、延庆寺塔等济源城区历史遗存串联参观。"},"keywords":["原城","夏都","庙街","龙山文化","二里头文化"]}'),
('zhiguogucheng', '轵国故城', '济源', '周', '都城遗址', '战国轵邑、秦汉轵县', '春秋—南北朝', '太行陉口要冲，战国名邑与汉代侯国城', 'zhiguogucheng.jpg', '{"id":"zhiguogucheng","name":"轵国故城","city":"济源","era":"周","type":"都城遗址","typeDesc":"战国轵邑、秦汉轵县","dynasty":"春秋—南北朝","cover":"🏰","image":"zhiguogucheng.jpg","summary":"太行陉口要冲，战国名邑与汉代侯国城","intro":"轵国故城位于济源市区南约六公里的轵城镇，北依太行、南近黄河，控制太行八陉之一的轵关陉。春秋时期这里逐渐形成城邑，战国时先后属韩、魏，是中原交通与军事重镇。秦代置轵县，西汉至南北朝时期多次作为侯国封邑。","archaeology":"考古调查显示，故城城垣范围约为1956米乘2088米，面积约518万平方米，城墙、城壕和城内遗存保存有较多历史信息。遗址出土东周及汉代板瓦、瓦当、陶器、货币等遗物，对研究春秋战国城邑制度和汉代侯国制度具有重要价值，2006年被公布为第六批全国重点文物保护单位。","relics":[{"name":"东周瓦当","desc":"当面纹饰具有春秋战国建筑材料特征，是研究轵邑官式建筑的重要线索。"},{"name":"汉代陶仓","desc":"随葬或生活用明器，反映汉代轵县农业、仓储和厚葬风俗。"}],"events":[{"time":"战国","title":"韩魏名邑轵城","desc":"轵城地处太行陉与黄河北岸通道，是战国时期重要城邑。"},{"time":"2006年","title":"全国重点文物保护单位","desc":"轵国故城被列入第六批全国重点文物保护单位。"}],"poems":[{"title":"城邑说明","author":"地方历史研究","content":"轵城因陉道而兴，是连接河内、上党与洛阳盆地的重要节点。"}],"tourism":{"address":"济源市轵城镇","openTime":"城址为露天遗址，参观以现场和当地公告为准","ticket":"以现场公告为准","tips":"可与泗涧古墓群、大明寺、轵城关帝庙一并了解古轵文化。"},"keywords":["轵国","轵邑","太行陉","侯国","战国城址"]}'),
('sijianmuqun', '泗涧古墓群', '济源', '汉唐', '墓葬群', '汉代轵国贵族官吏墓地', '汉代', '出土陶风车、桃都树、百花灯等汉代文物', 'sijianmuqun.jpg', '{"id":"sijianmuqun","name":"泗涧古墓群","city":"济源","era":"汉唐","type":"墓葬群","typeDesc":"汉代轵国贵族官吏墓地","dynasty":"汉代","cover":"⚱️","image":"sijianmuqun.jpg","summary":"出土陶风车、桃都树、百花灯等汉代文物","intro":"泗涧古墓群位于轵国故城南侧，是古轵地区汉代贵族、官吏和富户墓葬集中分布区。墓地背靠高台地，邻近故城，符合古代城邑与墓葬区分离布局。其出土器物造型丰富，反映汉代河内地区高超的陶塑工艺和社会生活。","archaeology":"考古发掘与清理中曾出土陶风车、桃都树、舞乐俑、百花灯、陶楼、陶仓等大量汉代遗物。其中陶风车对研究汉代农业加工机械具有重要价值，舞乐俑和百花灯则反映汉代乐舞、照明与丧葬观念。墓地具体保护级别仍需以文物部门名录核对。","relics":[{"name":"汉代陶风车","desc":"模拟风选谷物机械的明器，体现汉代农业机械和陶塑水平。"},{"name":"百花灯","desc":"多枝式陶灯，造型华丽，是汉代照明器具与神仙信仰结合的代表。"}],"events":[{"time":"汉代","title":"轵国贵族墓地形成","desc":"随着轵城政治、经济发展，城南形成规模较大的墓葬区。"},{"time":"考古清理","title":"大批汉代陶明器出土","desc":"陶风车、桃都树、舞乐俑等文物为研究汉代社会生活提供实物。"}],"poems":[{"title":"文物说明","author":"考古资料","content":"泗涧汉墓以生活化明器见长，是复原古轵社会风貌的重要窗口。"}],"tourism":{"address":"济源市轵城镇泗涧一带","openTime":"墓葬区以保护为主，不固定开放","ticket":"以现场公告为准","tips":"可先了解轵国故城，再查看墓地出土文物资料。"},"keywords":["泗涧","汉墓","陶风车","百花灯","古轵"]}'),
('jidumiao', '济渎庙', '济源', '汉唐', '古建筑', '祭祀济水的祠庙', '隋代创建，宋元明清沿用', '四渎庙中规模大、保存完整的济水神庙', 'jidumiao.jpg', '{"id":"jidumiao","name":"济渎庙","city":"济源","era":"汉唐","type":"古建筑","typeDesc":"祭祀济水的祠庙","dynasty":"隋代创建，宋元明清沿用","cover":"⛩","image":"jidumiao.jpg","summary":"四渎庙中规模大、保存完整的济水神庙","intro":"济渎庙又称清源祠，位于济源市，是古代祭祀“四渎”之一济水的礼制建筑。隋开皇二年，即公元582年创建，历代屡有重修和扩建。济水虽流程较短，但在古代国家祭祀体系中地位重要，济渎庙也成为河渎祭祀制度的重要实物。","archaeology":"庙内现存寝宫重建于宋开宝六年，即公元973年，是河南现存较早的木构建筑之一。建筑群还保存宋元明清时期殿宇、亭阁和碑碣四十余通，其中包括赵孟頫《投龙简记》等重要碑刻。1996年被公布为第四批全国重点文物保护单位。","relics":[{"name":"宋代寝宫木构","desc":"梁架与斗栱保留宋代木构特征，是研究河南早期木构建筑的重要实例。"},{"name":"《投龙简记》碑","desc":"碑刻书法与祭祀史料价值并重，传为赵孟頫相关书迹，是济渎庙重要碑刻。"}],"events":[{"time":"582年","title":"隋代创建济渎庙","desc":"国家祭祀济水的礼制建筑在济源建立。"},{"time":"1996年","title":"全国重点文物保护单位","desc":"济渎庙被列入第四批全国重点文物保护单位。"}],"poems":[{"title":"礼制说明","author":"古代祭祀制度","content":"江、河、淮、济为四渎，济渎庙是国家水神祭祀体系的重要组成。"}],"tourism":{"address":"济源市济渎大街","openTime":"一般对外开放，具体以场馆公告为准","ticket":"以景区公告为准","tips":"建议重点观看宋代寝宫、古碑刻和祭祀济水展陈。"},"keywords":["济渎庙","济水","四渎","宋代木构","祭祀"]}'),
('yanqingsita', '柴庄延庆寺塔', '济源', '宋', '古建筑', '北宋楼阁式砖塔', '北宋景祐年间', '六角七级砖塔，临龙潭而建，内嵌佛龛雕砖', 'yanqingsita.jpg', '{"id":"yanqingsita","name":"柴庄延庆寺塔","city":"济源","era":"宋","type":"古建筑","typeDesc":"北宋楼阁式砖塔","dynasty":"北宋景祐年间","cover":"🗼","image":"yanqingsita.jpg","summary":"六角七级砖塔，临龙潭而建，内嵌佛龛雕砖","intro":"延庆寺塔又称龙潭塔，位于济源市区西北约三公里的延庆寺旧址，因临济水西源龙潭而得名。塔于北宋景祐元年动工、景祐三年竣工，为六角七级楼阁式砖塔，高约28米，是豫西北宋代佛塔的重要实例。","archaeology":"塔体内嵌佛龛雕砖千余块，砖雕佛像、莲座和装饰纹样具有宋代佛教艺术特征。塔檐、斗栱和收分体现宋代砖塔营造技法。2006年，延庆寺塔作为重要古建筑被列入第六批全国重点文物保护单位。","relics":[{"name":"佛龛雕砖","desc":"模印佛像与莲座，数量较多，是研究宋代佛教造像和砖作工艺的实物。"},{"name":"龙潭塔砖","desc":"塔砖规格规整、砌筑坚固，反映北宋豫西北地区砖塔技术。"}],"events":[{"time":"1034—1036年","title":"北宋建塔","desc":"延庆寺塔于景祐年间建成，成为龙潭佛寺标志。"},{"time":"2006年","title":"全国重点文物保护单位","desc":"延庆寺塔被列入第六批全国重点文物保护单位。"}],"poems":[{"title":"景观说明","author":"地方文史","content":"龙潭塔影与济水源头相映，是济源宋代佛教建筑的代表。"}],"tourism":{"address":"济源市柴庄延庆寺旧址","openTime":"以现场开放情况为准","ticket":"以现场公告为准","tips":"可与济渎庙、原城遗址安排为济源城区历史线路。"},"keywords":["延庆寺塔","龙潭塔","北宋","佛塔","砖雕"]}'),
('fuchengzaoshang', '府城早商城址', '焦作', '夏商', '都城遗址', '早商方国都邑', '二里岗文化，含二里头至西周遗存', '1999年全国十大考古新发现之一', 'fuchengzaoshang.jpg', '{"id":"fuchengzaoshang","name":"府城早商城址","city":"焦作","era":"夏商","type":"都城遗址","typeDesc":"早商方国都邑","dynasty":"二里岗文化，含二里头至西周遗存","cover":"🏯","image":"fuchengzaoshang.jpg","summary":"1999年全国十大考古新发现之一","intro":"府城早商城址位于焦作市中站区府城村，地处黄河北岸、沁河以西的怀川地带。遗址主体属于商代二里岗时期，一般认为是早商方国都邑或重要军事城邑，并非商王朝统一都城。其发现丰富了黄河北岸早商时期政治格局研究。","archaeology":"遗址发现城垣、夯土基址和丰富文化层，包含二里头、二里岗、白家庄及西周时期遗存。1999年因其保存完整、年代明确、性质重要而入选全国十大考古新发现。2001年被公布为第五批全国重点文物保护单位。","relics":[{"name":"二里岗陶鬲","desc":"商代常见炊器，袋足和绳纹具有二里岗文化特征。"},{"name":"夯土建筑构件","desc":"城垣和房址夯层清晰，反映早商城邑筑城技术。"}],"events":[{"time":"早商","title":"黄河北岸城邑建立","desc":"府城成为商王朝控制怀川地区的重要方国或军事据点。"},{"time":"1999年","title":"全国十大考古新发现","desc":"府城遗址因重要考古价值入选年度十大考古新发现。"}],"poems":[{"title":"性质说明","author":"考古研究","content":"府城是早商方国都邑的重要代表，不宜直接称为商王都城。"}],"tourism":{"address":"焦作市中站区府城村","openTime":"遗址以现场保护为主，参观以公告为准","ticket":"以现场公告为准","tips":"可与 nearby 沁河、邘国故城等共同了解怀川方国历史。"},"keywords":["府城","早商","二里岗","方国","十大考古"]}'),
('yuguogucheng', '邘国故城', '焦作', '周', '都城遗址', '西周邘国封城', '西周—春秋', '周武王之子邘叔的封国城邑', 'yuguogucheng.jpg', '{"id":"yuguogucheng","name":"邘国故城","city":"焦作","era":"周","type":"都城遗址","typeDesc":"西周邘国封城","dynasty":"西周—春秋","cover":"🏰","image":"yuguogucheng.jpg","summary":"周武王之子邘叔的封国城邑","intro":"邘国故城位于焦作沁阳市一带，是西周分封制度下的诸侯国城。史载周武王之子邘叔被封于邘，其地扼守太行南口与沁河通道，是周王朝控制河内地区的重要节点。春秋以后，邘国渐被周边强国兼并。","archaeology":"调查发现城址、夯土城墙及周代遗物，文化面貌可追溯至西周并延续至春秋。遗址对研究西周分封、诸侯国布局及太行陉道交通具有重要价值，2013年被公布为第七批全国重点文物保护单位。","relics":[{"name":"西周板瓦","desc":"周代建筑材料，说明城内曾有等级较高的建筑。"},{"name":"青铜车马器残件","desc":"反映封国贵族出行、礼制和军事活动。"}],"events":[{"time":"西周初年","title":"邘叔受封","desc":"周武王分封子弟于邘，建立诸侯国。"},{"time":"2013年","title":"全国重点文物保护单位","desc":"邘国故城被列入第七批全国重点文物保护单位。"}],"poems":[{"title":"分封说明","author":"西周制度","content":"邘国是周王朝在河内地区建立的重要封国，体现“封建亲戚以藩屏周”。"}],"tourism":{"address":"焦作市沁阳市境内","openTime":"以遗址现场和当地公告为准","ticket":"以现场公告为准","tips":"可与府城早商城址串联，理解商、周方国制度演变。"},"keywords":["邘国","邘叔","西周","分封","沁阳"]}'),
('shanyanggucheng', '山阳故城', '焦作', '汉唐', '都城遗址', '汉山阳县治与山阳公封邑', '战国—汉代', '汉献帝禅位后受封山阳公的封邑城', 'shanyanggucheng.jpg', '{"id":"shanyanggucheng","name":"山阳故城","city":"焦作","era":"汉唐","type":"都城遗址","typeDesc":"汉山阳县治与山阳公封邑","dynasty":"战国—汉代","cover":"🏯","image":"shanyanggucheng.jpg","summary":"汉献帝禅位后受封山阳公的封邑城","intro":"山阳故城位于焦作市山阳区墙南村一带，战国至汉代持续使用。汉代为山阳县治所。东汉延康元年，即公元220年，汉献帝刘协禅位于曹丕后被降封为山阳公，此城成为其封邑，但并非汉献帝在位时期的都城。","archaeology":"故城周长约五千米，城墙、城壕及城内遗存保留了汉代县城形制。遗址出土汉代瓦当、陶器、砖瓦、钱币等遗物，是研究汉魏禅代、县邑制度和河内城市史的重要资料，2006年被列入第六批全国重点文物保护单位。","relics":[{"name":"汉代云纹瓦当","desc":"建筑构件，反映山阳县官署和城邑建筑等级。"},{"name":"陶井圈","desc":"汉代城市生活设施构件，可用于研究故城供水与居民生活。"}],"events":[{"time":"220年","title":"山阳公封邑","desc":"刘协禅位后被封为山阳公，山阳故城成为其封邑。"},{"time":"2006年","title":"全国重点文物保护单位","desc":"山阳故城被列入第六批全国重点文物保护单位。"}],"poems":[{"title":"史迹说明","author":"汉魏历史研究","content":"山阳故城见证汉魏禅代，但它是封邑城，不是东汉帝都。"}],"tourism":{"address":"焦作市山阳区墙南村","openTime":"城址以现场保护为主，参观以公告为准","ticket":"以现场公告为准","tips":"可与修武汉献帝禅陵联系起来参观。"},"keywords":["山阳故城","汉献帝","山阳公","汉代县城","汉魏禅代"]}'),
('chanxianling', '汉献帝禅陵', '焦作', '汉唐', '墓葬群', '东汉逊帝陵寝', '曹魏初', '东汉献帝刘协陵寝，保存有帝陵规制', 'chanxianling.jpg', '{"id":"chanxianling","name":"汉献帝禅陵","city":"焦作","era":"汉唐","type":"墓葬群","typeDesc":"东汉逊帝陵寝","dynasty":"曹魏初","cover":"⚰️","image":"chanxianling.jpg","summary":"东汉献帝刘协陵寝，保存有帝陵规制","intro":"汉献帝禅陵位于焦作市修武县，是东汉末代皇帝刘协的陵墓。刘协禅位后被封为山阳公，去世后谥孝献皇帝，以汉代天子礼制安葬。禅陵与山阳故城共同构成汉魏禅代历史的重要史迹。","archaeology":"陵区保存封土、陵地及部分神道建筑遗存，是豫北地区少见的帝陵级墓葬。现场砖瓦、石刻和陵寝布局对研究东汉帝陵制度及曹魏优待逊帝政策具有价值。2013年被公布为第七批全国重点文物保护单位。","relics":[{"name":"陵寝绳纹砖","desc":"具有汉代砖瓦特征，是陵区建筑材料。"},{"name":"神道石刻残件","desc":"反映帝陵神道制度，具体残件需结合考古资料识别。"}],"events":[{"time":"曹魏初","title":"汉献帝安葬","desc":"刘协去世后以汉天子礼葬于禅陵。"},{"time":"2013年","title":"全国重点文物保护单位","desc":"禅陵被列入第七批全国重点文物保护单位。"}],"poems":[{"title":"史迹说明","author":"汉魏史研究","content":"禅陵是东汉帝陵制度的尾声，也是汉魏政权更替的实物见证。"}],"tourism":{"address":"焦作市修武县古汉村一带","openTime":"以陵园现场公告为准","ticket":"以现场公告为准","tips":"建议与山阳故城一并参观，理解献帝晚年封邑生活。"},"keywords":["禅陵","汉献帝","东汉帝陵","修武","山阳公"]}'),
('dangyangyu', '当阳峪窑址', '焦作', '宋', '窑址', '北方民间瓷窑遗址', '源于唐，盛于北宋，元渐衰', '以绞胎瓷和剔划花工艺著称的宋代窑场', 'dangyangyu.jpg', '{"id":"dangyangyu","name":"当阳峪窑址","city":"焦作","era":"宋","type":"窑址","typeDesc":"北方民间瓷窑遗址","dynasty":"源于唐，盛于北宋，元渐衰","cover":"🏺","image":"dangyangyu.jpg","summary":"以绞胎瓷和剔划花工艺著称的宋代窑场","intro":"当阳峪窑址位于焦作市修武县当阳峪村，又称修武窑、焦作窑，是宋代北方重要民间瓷窑群。窑场兼烧绞胎瓷、白地黑花、剔划花、刻花填彩、钧釉等品种，其中绞胎瓷纹理内外相通，又称透花瓷。","archaeology":"遗址范围东西约两千米、南北约一千米，调查发现窑炉、窑具、瓷片堆积和作坊遗迹。出土瓷片显示其工艺受定窑、磁州窑和钧窑等多系统影响，又形成鲜明地方特色。2006年被公布为第六批全国重点文物保护单位，绞胎瓷烧制技艺列入国家级非物质文化遗产。","relics":[{"name":"绞胎瓷片","desc":"胎体纹理由不同色泥绞合而成，内外一致，是当阳峪最具代表性的产品。"},{"name":"剔划花瓷瓶残件","desc":"花纹层次分明，体现窑工娴熟的刻划和化妆土装饰工艺。"}],"events":[{"time":"北宋","title":"当阳峪窑兴盛","desc":"黄河北岸形成规模庞大的民间瓷窑生产区。"},{"time":"2006年","title":"全国重点文物保护单位","desc":"当阳峪窑址被列入第六批全国重点文物保护单位。"}],"poems":[{"title":"工艺说明","author":"陶瓷研究","content":"当阳峪绞胎瓷以泥纹成画，是宋代北方民窑创造性的集中体现。"}],"tourism":{"address":"焦作市修武县当阳峪村","openTime":"窑址和相关展馆以当地公告为准","ticket":"以现场公告为准","tips":"可重点观看绞胎瓷标本和现代绞胎瓷复原烧制。"},"keywords":["当阳峪","绞胎瓷","宋代窑址","修武窑","北方民窑"]}'),
('dahecun', '大河村遗址', '郑州', '仰韶', '古建筑', '聚落遗址', '仰韶文化晚期—龙山文化（约6800—4000年前）', '出土国宝“彩陶双连壶”的史前聚落', 'dahecun.jpg', '{"id":"dahecun","name":"大河村遗址","city":"郑州","era":"仰韶","type":"古建筑","typeDesc":"聚落遗址","dynasty":"仰韶文化晚期—龙山文化（约6800—4000年前）","cover":"🏘️","image":"dahecun.jpg","summary":"出土国宝“彩陶双连壶”的史前聚落","intro":"大河村遗址位于郑州市金水区，是黄河流域一处延续数千年的史前大型聚落遗址，文化层叠压关系清晰，包含仰韶文化、龙山文化等多个阶段遗存。遗址内发现大量房基、窖穴、墓葬和陶窑，出土的彩陶纹饰繁丽，其中“彩陶双连壶”造型独特，象征两族结盟，是河南博物院镇馆之宝之一。","archaeology":"1972年以来历经数十次发掘，揭露面积5000余平方米，发现房基50余座、窖穴500余座、墓葬300余座，出土各类文物数万件。遗址展示的“木骨整塑陶墙”建筑技术在中国史前建筑史上独树一帜。大河村遗址博物馆是国内较早建成开放的史前遗址类博物馆，真实复原了仰韶时期村落面貌。","relics":[{"name":"彩陶双连壶","desc":"两壶腹部相连相通，造型独特，被认为是部落结盟或礼仪活动中使用的特殊器物，为仰韶文化晚期珍品。"},{"name":"白衣彩陶钵","desc":"先施白色陶衣再以红、褐彩绘纹，色彩层次丰富，是\\"大河村类型\\"彩陶的命名性特征。"}],"events":[{"time":"1972年","title":"大规模考古发掘","desc":"文物部门对遗址进行持续发掘，确认其丰富的仰韶、龙山文化堆积。"},{"time":"2001年","title":"入选全国重点文物保护单位","desc":"大河村遗址被国务院公布为第五批全国重点文物保护单位。"}],"poems":[{"title":"学界评语","author":"大河村遗址博物馆","content":"彩陶双连壶，连心又连理——黄河先民“合和”精神的物化见证。"}],"tourism":{"address":"郑州市金水区大河村遗址博物馆（连霍高速与中州大道交叉口附近）","openTime":"周二至周日，具体以场馆公告为准","ticket":"免费开放，以场馆公告为准","tips":"馆内可体验模拟考古与彩陶绘制，适合亲子研学。"},"keywords":["彩陶双连壶","河南博物院","聚落","郑州","陶墙建筑"]}')
INSERT INTO heritage_site (id, name, city, era, type, type_desc, dynasty, summary, image, detail_json) VALUES
('xinzha', '新砦遗址', '郑州', '龙山', '都城遗址', '夏代早期都邑', '龙山文化晚期—新砦期（约3900—3600年前）', '龙山向二里头过渡的关键都邑，探寻“最早的中国”前夜', 'xinzha.jpg', '{"id":"xinzha","name":"新砦遗址","city":"郑州","era":"龙山","type":"都城遗址","typeDesc":"夏代早期都邑","dynasty":"龙山文化晚期—新砦期（约3900—3600年前）","cover":"🏰","image":"xinzha.jpg","summary":"龙山向二里头过渡的关键都邑，探寻“最早的中国”前夜","intro":"新砦遗址位于郑州新密市刘寨镇，是一处介于龙山文化与二里头文化之间的过渡期大型城址，年代约在公元前1900年前后。遗址发现外壕、城墙、内壕三重防御体系及大型建筑基址，出土以鬶、盉、深腹罐为特征的“新砦期”陶器群，被学界视为探索夏文化起源、连接龙山与二里头的关键一环。","archaeology":"2002—2003年，北京大学考古文博学院与郑州市文物考古研究院联合发掘，确认城址面积约100万平方米，发现双重城壕与中心区大型建筑基址，出土“兽面纹”陶器残片等具有礼制色彩的重要遗物，为研究夏代早期国家形态提供了珍贵材料。","relics":[{"name":"新砦期陶鬶","desc":"新砦期（龙山文化晚期至二里头文化之间）典型炊器，是探索夏文化的关键过渡期器物。"},{"name":"刻画符号陶片","desc":"器表刻有疑似原始文字的符号，为研究早期文字起源提供重要线索。"}],"events":[{"time":"2002年","title":"确认大型城址","desc":"考古发掘确认新砦遗址具有城墙、外壕、内壕多重防御体系的大型城址性质。"},{"time":"2006年","title":"入选全国重点文物保护单位","desc":"新砦遗址被国务院公布为第六批全国重点文物保护单位。"}],"poems":[{"title":"学界评语","author":"夏商周断代工程相关研究","content":"新砦期文化是连接龙山文化与二里头文化的“桥梁”，夏文化探源的关键坐标。"}],"tourism":{"address":"郑州市新密市刘寨镇新砦村","openTime":"考古遗址现场，参观以当地文保部门安排为准","ticket":"暂不设门票，以文保公告为准","tips":"遗址为考古重地，参观请遵守现场管理，可结合新密古城寨遗址联线探访。"},"keywords":["夏文化","新砦期","城址","新密","龙山"]}'),
('zhengzhoushangcheng', '郑州商城遗址', '郑州', '夏商', '都城遗址', '商代前期都城', '商代早期（约3600年前）', '商汤亳都，3600年城址未迁的“商都郑州”', 'zhengzhoushangcheng.jpg', '{"id":"zhengzhoushangcheng","name":"郑州商城遗址","city":"郑州","era":"夏商","type":"都城遗址","typeDesc":"商代前期都城","dynasty":"商代早期（约3600年前）","cover":"⚱️","image":"zhengzhoushangcheng.jpg","summary":"商汤亳都，3600年城址未迁的“商都郑州”","intro":"郑州商城遗址位于郑州市区中心，是商代早期都城遗址，距今约3600年，被多数学者认定为商汤所建“亳都”。城址平面近长方形，周长约7公里，城墙以版筑法夯筑，现存地面城墙最高处约5米。遗址出土大批青铜礼器、玉器和原始瓷器，其中杜岭方鼎、兽面纹铜方鼎等重器印证了其王都地位，郑州由此获誉“商都”。","archaeology":"1950年发现，1955年确认城垣；1970年代在城址内发现张寨南街、向阳食品厂等多处青铜器窖藏坑，出土杜岭方鼎（高100厘米，重86.4千克）等国之重器；宫殿区位于城内东北部，发现大型夯土基址；城外分布铸铜、制骨、制陶手工业作坊。2015年郑州商都遗址博物院筹建，2022年开放。","relics":[{"name":"杜岭方鼎","desc":"商代早期大型青铜方鼎，造型庄重，是郑州商城作为商代早期王都的重要实物证据。"},{"name":"原始青瓷尊","desc":"商代原始瓷器，胎质坚硬、施青釉，把中国瓷器烧造史大幅提前。"}],"events":[{"time":"1950年","title":"遗址发现","desc":"郑州市区发现商代文化遗存，随后确认城垣走向。"},{"time":"1961年","title":"入选全国重点文物保护单位","desc":"郑州商城遗址被国务院公布为第一批全国重点文物保护单位。"},{"time":"2022年","title":"郑州商都遗址博物院开放","desc":"博物院系统展示“亳都”3600年的历史变迁。"}],"poems":[{"title":"《诗经·商颂·玄鸟》","author":"佚名","content":"天命玄鸟，降而生商，宅殷土芒芒。"}],"tourism":{"address":"郑州市管城回族区郑州商都遗址博物院（东大街与城东路交叉口）","openTime":"周二至周日，具体以场馆公告为准","ticket":"免费预约参观，以场馆公告为准","tips":"登上商城遗址城墙步道可俯瞰“城摞城”格局；博物院附近有商城遗址公园，适合Citywalk。"},"keywords":["商汤亳都","杜岭方鼎","3600年","郑州","青铜器窖藏"]}'),
('huangye', '巩义黄冶窑址', '郑州', '汉唐', '窑址', '唐代三彩窑址', '唐代', '唐三彩的故乡，丝绸之路上的艺术名窑', 'huangye.jpg', '{"id":"huangye","name":"巩义黄冶窑址","city":"郑州","era":"汉唐","type":"窑址","typeDesc":"唐代三彩窑址","dynasty":"唐代","cover":"🎨","image":"huangye.jpg","summary":"唐三彩的故乡，丝绸之路上的艺术名窑","intro":"黄冶窑址位于郑州市巩义市站街镇，地处黄河南岸，是唐代著名的三彩釉陶窑址，也是目前中国发现规模最大的唐三彩窑址群。唐代三彩器以黄、绿、白三色为基调，造型涵盖人物、动物、器皿，远销海内外，是丝绸之路文化交流的物证。黄冶窑的发现为唐三彩“产地洛阳说”提供了决定性证据。","archaeology":"1976年首次调查发现，2002—2004年河南省文物考古研究所正式发掘，揭露窑炉、作坊、澄泥池等遗迹，出土大量三彩器、素烧器、窑具与模具残片，确认黄冶窑烧造时间自盛唐延续至北宋，产品除三彩外还有绞胎器、唐青花等。","relics":[{"name":"唐三彩窑具与模具","desc":"黄冶窑出土的大量窑具、印模，完整还原了唐三彩的成型与烧造流程。"},{"name":"白釉蓝彩器物","desc":"白地蓝彩的唐代器物残片，被视为青花瓷起源研究的关键材料。"}],"events":[{"time":"1976年","title":"窑址被发现","desc":"文物部门在巩义黄冶村发现唐三彩窑址线索。"},{"time":"2006年","title":"入选全国重点文物保护单位","desc":"巩义黄冶窑址被国务院公布为第六批全国重点文物保护单位。"}],"poems":[{"title":"学界评语","author":"唐三彩研究","content":"黄冶窑火映千年，三彩流光走丝路。"}],"tourism":{"address":"郑州市巩义市站街镇黄冶村（巩义市博物馆有相关陈列）","openTime":"窑址现场参观以当地文保部门安排为准","ticket":"无需门票，以现场公告为准","tips":"建议先到巩义市博物馆了解唐三彩文化，再实地探访窑址，并可联游巩义石窟寺。"},"keywords":["唐三彩","窑址","巩义","丝路","绞胎器"]}'),
('liulige', '琉璃阁遗址', '新乡', '夏商', '墓葬群', '商至汉遗址与墓葬区', '商—汉', '近代河南考古史上的重要遗址和墓葬区', 'liulige.jpg', '{"id":"liulige","name":"琉璃阁遗址","city":"新乡","era":"夏商","type":"墓葬群","typeDesc":"商至汉遗址与墓葬区","dynasty":"商—汉","cover":"⚱️","image":"liulige.jpg","summary":"近代河南考古史上的重要遗址和墓葬区","intro":"琉璃阁遗址位于新乡辉县市，遗址和墓葬使用时间长，文化堆积从商代延续至汉代，集中使用约一千五百年。区域内既有生活遗址，也有商、战国和汉代墓葬，是研究新乡地区先秦方国、魏国贵族墓葬和汉代社会的重要资料。","archaeology":"1935年至1952年间，遗址历经多次发掘，出土青铜器、陶器、玉器等大量遗物。商代墓葬和战国墓葬等级较高，部分器物与辉县、汲县一带魏国贵族群体有关。遗址的具体国保批次仍需以最新文物名录核对。","relics":[{"name":"商代铜爵","desc":"青铜酒礼器，可用于研究商代礼制在豫北地区的传播。"},{"name":"战国陶鼎","desc":"魏国墓葬常见礼器，反映战国时期礼制变革和随葬风俗。"}],"events":[{"time":"商—汉","title":"长期沿用的遗址与墓地","desc":"琉璃阁区域延续约一千五百年，形成丰富文化层。"},{"time":"1935—1952年","title":"多次考古发掘","desc":"近代考古工作者在此清理多批墓葬，取得重要研究资料。"}],"poems":[{"title":"考古说明","author":"近代考古史","content":"琉璃阁是豫北商至汉文化序列的重要节点，也是中国早期考古学术史的一部分。"}],"tourism":{"address":"新乡市辉县市琉璃阁一带","openTime":"以遗址保护和当地公告为准","ticket":"以现场公告为准","tips":"可与共城城址、山彪镇墓地共同了解辉县、卫辉考古群。"},"keywords":["琉璃阁","辉县考古","商墓","战国墓","汉代遗址"]}'),
('biganmiao', '比干庙', '新乡', '夏商', '古建筑', '庙墓合一祠庙', '北魏创建，明清重建', '纪念商代忠臣比干的祠庙，是林氏寻根地', 'biganmiao.jpg', '{"id":"biganmiao","name":"比干庙","city":"新乡","era":"夏商","type":"古建筑","typeDesc":"庙墓合一祠庙","dynasty":"北魏创建，明清重建","cover":"⛩","image":"biganmiao.jpg","summary":"纪念商代忠臣比干的祠庙，是林氏寻根地","intro":"比干庙位于新乡卫辉市，是庙墓合一的纪念建筑群，祭祀史传商代忠臣比干。比干墓相传由周武王封墓，后世屡有祭祀。庙宇始建于北魏太和十八年，现存建筑多为明清时期遗构，是豫北重要祠庙建筑。","archaeology":"建筑群保持前庙后墓格局，保存殿宇、牌坊、碑刻、墓冢等。庙内有传孔子剑刻“殷比干墓”碑、北魏《孝文帝吊比干文》碑及乾隆御碑等，部分碑刻经历后世重刻。1996年，比干庙被公布为第四批全国重点文物保护单位。","relics":[{"name":"《孝文帝吊比干文》碑","desc":"碑文兼具历史与书法价值，是研究北朝祭祀和比干信仰的重要资料。"},{"name":"比干墓冢","desc":"纪念性墓冢，年代不可作考古学商王陵确认，应与祠庙作为整体看待。"}],"events":[{"time":"494年","title":"北魏建庙祭祀","desc":"孝文帝时期为比干建立祠庙，形成官方祭祀传统。"},{"time":"1996年","title":"全国重点文物保护单位","desc":"比干庙被列入第四批全国重点文物保护单位。"}],"poems":[{"title":"文化说明","author":"寻根文化","content":"比干庙承载忠谏文化与林氏寻根记忆，是黄河文化叙事中的重要祠庙。"}],"tourism":{"address":"新乡市卫辉市比干庙村","openTime":"一般对外开放，以景区公告为准","ticket":"以景区公告为准","tips":"建议重点观看碑刻、墓冢和庙墓合一格局。"},"keywords":["比干庙","比干","卫辉","祠庙","林氏寻根"]}'),
('gongcheng', '共城城址', '新乡', '周', '都城遗址', '西周共国都城', '西周—春秋', '西周共国都城，与“共和行政”历史相关', 'gongcheng.jpg', '{"id":"gongcheng","name":"共城城址","city":"新乡","era":"周","type":"都城遗址","typeDesc":"西周共国都城","dynasty":"西周—春秋","cover":"🏰","image":"gongcheng.jpg","summary":"西周共国都城，与“共和行政”历史相关","intro":"共城城址位于新乡辉县市，始建于西周初年，是西周共国都城和共伯和封邑。公元前841年，国人暴动后出现“共和行政”，中国历史由此有了明确而连续的纪年。共城是研究西周诸侯国都城和纪年开端的重要遗址。","archaeology":"城址发现城墙、城壕、夯土基址及周代陶片、板瓦等遗物，都城轮廓较清楚。其年代可追溯至西周并延续至春秋，2006年被公布为第六批全国重点文物保护单位。","relics":[{"name":"西周板瓦","desc":"目前发现较早的建筑材料之一，说明共城具有较高建筑等级。"},{"name":"青铜车马器","desc":"封国贵族礼制和交通活动的实物见证。"}],"events":[{"time":"前841年","title":"共和行政","desc":"共伯和相关历史与中国确切纪年开端联系在一起。"},{"time":"2006年","title":"全国重点文物保护单位","desc":"共城城址被列入第六批全国重点文物保护单位。"}],"poems":[{"title":"纪年说明","author":"历史研究","content":"共和元年是中国历史确切纪年的重要开端，共城因此具有特殊坐标意义。"}],"tourism":{"address":"新乡市辉县市境内","openTime":"城址以现场保护为主，参观以公告为准","ticket":"以现场公告为准","tips":"可与琉璃阁、山彪镇墓地构成豫北两周考古线路。"},"keywords":["共城","共国","共和行政","西周","辉县"]}'),
('shanbiaozhen', '山彪镇战国墓地', '新乡', '周', '墓葬群', '战国魏国贵族墓地', '战国', '出土水陆攻战纹铜鉴等重要青铜器', 'shanbiaozhen.jpg', '{"id":"shanbiaozhen","name":"山彪镇战国墓地","city":"新乡","era":"周","type":"墓葬群","typeDesc":"战国魏国贵族墓地","dynasty":"战国","cover":"🏺","image":"shanbiaozhen.jpg","summary":"出土水陆攻战纹铜鉴等重要青铜器","intro":"山彪镇战国墓地位于新乡卫辉市唐庄镇山彪村，是战国时期魏国贵族墓地。1935年考古发掘中出土多件青铜器，其中水陆攻战纹铜鉴以人物战斗、划船、击鼓等图案闻名，是研究战国战争、礼制和青铜画像艺术的重要实物。","archaeology":"墓地清理战国贵族墓葬，出土青铜鉴、鼎、壶、车马器及陶器等。墓葬等级较高，反映魏国贵族礼制和工艺水平。地方资料与省级综述对其保护级别表述不一，需以最新文物保护名录核对。","relics":[{"name":"水陆攻战纹铜鉴","desc":"器表刻划水陆交战场景，是战国时期战争史和青铜艺术的重要资料。"},{"name":"魏国陶壶","desc":"具有战国魏墓器物特征，可用于墓葬分期和文化比较。"}],"events":[{"time":"战国","title":"魏国贵族墓地形成","desc":"山彪镇一带埋葬魏国高级贵族，随葬大量青铜器。"},{"time":"1935年","title":"考古发掘","desc":"墓地经科学清理，水陆攻战纹铜鉴等重要文物出土。"}],"poems":[{"title":"文物说明","author":"青铜器研究","content":"水陆攻战纹铜鉴以图像记录战争，是战国社会风貌的立体史料。"}],"tourism":{"address":"新乡市卫辉市唐庄镇山彪村","openTime":"墓地以保护为主，参观以公告为准","ticket":"以现场公告为准","tips":"可与共城、琉璃阁和比干庙安排为新乡北县历史线路。"},"keywords":["山彪镇","魏国墓地","水陆攻战纹铜鉴","战国","卫辉"]}'),
('linglongta', '玲珑塔', '新乡', '宋', '古建筑', '宋代楼阁式斜塔', '北宋崇宁年间', '黄河北岸滩区附近的宋代砖塔，又称善护寺塔', 'linglongta.jpg', '{"id":"linglongta","name":"玲珑塔","city":"新乡","era":"宋","type":"古建筑","typeDesc":"宋代楼阁式斜塔","dynasty":"北宋崇宁年间","cover":"🗼","image":"linglongta.jpg","summary":"黄河北岸滩区附近的宋代砖塔，又称善护寺塔","intro":"玲珑塔位于新乡平原城乡一体化示范区原武镇，又称善护寺塔，始建于北宋崇宁年间。塔身历经地震、水患和后世修缮，形成明显倾斜姿态，是豫北宋代佛塔和黄河灾害史研究的重要实物。","archaeology":"玲珑塔为楼阁式砖塔，塔体使用规格较统一的青砖砌筑，现存砖雕佛龛、檐部和塔心室等结构。1963年被列为河南省文物保护单位，2013年被公布为第七批全国重点文物保护单位。其地临近黄河滩区，见证历代黄河水文环境变化。","relics":[{"name":"宋代砖雕佛像","desc":"塔内砖雕佛龛和佛像具有宋代佛教艺术特征。"},{"name":"善护寺塔砖","desc":"塔砖质地坚硬、砌筑规整，是研究宋代砖塔工艺的材料。"}],"events":[{"time":"北宋崇宁","title":"修建善护寺塔","desc":"玲珑塔在原武一带建成，成为佛寺标志。"},{"time":"2013年","title":"全国重点文物保护单位","desc":"玲珑塔被列入第七批全国重点文物保护单位。"}],"poems":[{"title":"景观说明","author":"地方文史","content":"玲珑塔斜而不倒，既见宋代营造技艺，也见黄河水患与修缮历史。"}],"tourism":{"address":"新乡市平原示范区原武镇","openTime":"以现场公告为准","ticket":"以现场公告为准","tips":"可结合黄河滩区、原武古镇了解新乡黄河水文与佛教建筑。"},"keywords":["玲珑塔","善护寺塔","宋代斜塔","原武","黄河滩区"]}'),
('dongjing', '北宋东京城遗址', '开封', '宋', '都城遗址', '北宋都城遗址', '北宋（公元960—1127年）', '《清明上河图》描绘的梦华之城，“城摞城”奇观所在', 'dongjing.jpg', '{"id":"dongjing","name":"北宋东京城遗址","city":"开封","era":"宋","type":"都城遗址","typeDesc":"北宋都城遗址","dynasty":"北宋（公元960—1127年）","cover":"🏮","image":"dongjing.jpg","summary":"《清明上河图》描绘的梦华之城，“城摞城”奇观所在","intro":"北宋东京城（今开封）是当时世界上人口最多、经济最繁荣的都城，《东京梦华录》所载“八荒争凑，万国咸通”正是其盛况写照。城址为外城、内城、皇城三重城垣格局，埋藏于今日开封地下8—12米，形成罕见的“城摞城”奇观。张择端《清明上河图》即描绘汴河两岸的市井繁华。","archaeology":"1981年龙亭湖清淤发现明周王府遗址，由此揭开北宋东京城考古序幕；此后确认外城、内城、皇城范围及汴河、蔡河河道走向，发掘州桥、新郑门遗址等。东京城遗址于1988年列入全国重点文物保护单位，城摞城遗址博物馆以分层剖面直观展示历代城址叠压关系。","relics":[{"name":"\\"城摞城\\"地层剖面","desc":"不同朝代的开封城层层叠压，直观呈现黄河泛滥与城市重建的历史，堪称活的地质年表。"},{"name":"北宋御街遗迹","desc":"北宋东京城南北中轴线上的御道遗存，与《东京梦华录》记载相互印证。"}],"events":[{"time":"公元960年","title":"北宋定都开封","desc":"赵匡胤建宋，东京成为百万人口的世界级大都市。"},{"time":"1981年","title":"城摞城考古发现","desc":"龙亭湖清淤发现明代周王府遗址，拉开东京城考古序幕。"},{"time":"1988年","title":"入选全国重点文物保护单位","desc":"北宋东京城遗址被国务院公布为第三批全国重点文物保护单位。"}],"poems":[{"title":"《汴京元夕》","author":"李梦阳（明）","content":"中山孺子倚新妆，郑女燕姬独擅场。齐唱宪王春乐府，金梁桥外月如霜。"}],"tourism":{"address":"开封市龙亭区（城摞城遗址博物馆、宋都皇城旅游度假区）","openTime":"具体以场馆公告为准","ticket":"以场馆公告为准","tips":"城摞城遗址博物馆的历代城垣剖面是必看内容；清明上河园实景演绎汴京生活。"},"keywords":["清明上河图","东京梦华录","城摞城","开封","北宋都城"]}'),
('tieta', '开封铁塔', '开封', '宋', '古建筑', '北宋琉璃砖塔', '北宋（公元1049年始建）', '千年不倒的“天下第一塔”，琉璃砖砌筑的北宋建筑奇迹', 'tieta.jpg', '{"id":"tieta","name":"开封铁塔","city":"开封","era":"宋","type":"古建筑","typeDesc":"北宋琉璃砖塔","dynasty":"北宋（公元1049年始建）","cover":"🗼","image":"tieta.jpg","summary":"千年不倒的“天下第一塔”，琉璃砖砌筑的北宋建筑奇迹","intro":"开封铁塔本名“开宝寺塔”，始建于北宋皇祐元年（1049年），因塔身以铁褐色琉璃砖砌筑、远望如铁铸而得名。塔高55.88米，为八角十三层楼阁式砖塔，历经近千年风雨与多次黄河水患、地震而巍然屹立，被誉为“天下第一塔”，是北宋建筑技术与艺术的杰出代表。","archaeology":"铁塔为北宋东京城留存至今的最高建筑，塔身砖雕佛像、菩萨、飞天、麒麟等图案精美绝伦，琉璃砖面施以“铁色”釉。1961年被国务院公布为第一批全国重点文物保护单位。塔内砖砌螺旋登道可登临远眺，俯瞰开封城“悬河”与古城格局。","relics":[{"name":"琉璃砖雕佛像","desc":"铁塔通体以褐色琉璃砖砌筑，砖面模印飞天、菩萨、麒麟等图案，故有\\"铁塔\\"之称。"},{"name":"宋代琉璃飞天砖","desc":"砖面浮雕飞天、乐伎形象，线条生动，是北宋琉璃工艺的杰出代表。"}],"events":[{"time":"公元1049年","title":"铁塔建成","desc":"为供奉佛舍利，在开宝寺福胜院内建成木塔，后木塔焚毁，改以琉璃砖塔重建。"},{"time":"1961年","title":"入选全国重点文物保护单位","desc":"祐国寺塔（铁塔）被国务院公布为第一批全国重点文物保护单位。"}],"poems":[{"title":"《梦溪笔谈》","author":"沈括（宋）","content":"开宝寺塔在京师诸塔中最高，而制度甚精。"}],"tourism":{"address":"开封市龙亭区北门大街铁塔公园","openTime":"具体以景区公告为准","ticket":"以景区公告为准","tips":"登塔可俯瞰古城中轴线；景区内接引殿、天下第一塔碑刻值得细看。"},"keywords":["开宝寺塔","琉璃砖","天下第一塔","开封","北宋"]}'),
('zhouqiao', '州桥及附近汴河遗址', '开封', '宋', '古建筑', '北宋桥梁与河道遗址', '北宋至明代', '2022年度全国十大考古新发现，重现《东京梦华录》州桥夜市', 'zhouqiao.jpg', '{"id":"zhouqiao","name":"州桥及附近汴河遗址","city":"开封","era":"宋","type":"古建筑","typeDesc":"北宋桥梁与河道遗址","dynasty":"北宋至明代","cover":"🌉","image":"zhouqiao.jpg","summary":"2022年度全国十大考古新发现，重现《东京梦华录》州桥夜市","intro":"州桥是北宋东京城御街与汴河交汇处的著名桥梁，孟元老《东京梦华录》记载其旁夜市“直至三更尽，才五更又复开张”。2022年，州桥及附近汴河遗址考古发掘成果公布，明代州桥桥面、北宋石壁浮雕海马瑞兽等遗迹重见天日，实证了东京城“城摞城”格局，入选2022年度全国十大考古新发现。","archaeology":"2020—2022年，河南省文物考古研究院与开封市文物考古研究所联合发掘，揭露出明代州桥本体、北宋—明代汴河河道及两岸石壁。北宋石壁浮雕现存约16米，雕刻海马瑞兽、祥云等纹样，工艺精湛，为首次发现的北宋都城核心区大型浮雕艺术遗存。","relics":[{"name":"汴河石壁海马瑞兽浮雕","desc":"州桥遗址石壁上的巨幅海马、瑞兽、仙鹤浮雕，是近年北宋东京城考古的重大发现。"},{"name":"明代州桥桥体遗存","desc":"宋代汴河州桥之上叠压的明代桥梁遗存，清晰记录了州桥自宋至明的沿用与改建过程。"}],"events":[{"time":"北宋","title":"州桥夜市繁盛","desc":"州桥位于御街与汴河交汇处，是东京城最繁华的商业地标之一。"},{"time":"2022年","title":"入选全国十大考古新发现","desc":"州桥及附近汴河遗址考古成果入选2022年度全国十大考古新发现。"}],"poems":[{"title":"《东京梦华录》","author":"孟元老","content":"自州桥南去……夜市直至三更尽，才五更又复开张。如要闹去处，通晓不绝。"}],"tourism":{"address":"开封市鼓楼区中山路州桥遗址（州桥及附近汴河遗址保护展示）","openTime":"以遗址展馆公告为准","ticket":"以展馆公告为准","tips":"石壁浮雕海马瑞兽为镇址之宝；可与开封府、鼓楼夜市串联为“州桥—汴梁”主题线路。"},"keywords":["州桥","汴河","东京梦华录","十大考古新发现","开封"]}'),
('xishuipo', '西水坡遗址', '濮阳', '仰韶', '墓葬群', '仰韶文化墓葬群', '仰韶文化中期（约6500年前）', '出土蚌塑“中华第一龙”的史前墓葬，龙图腾的祖源', 'xishuipo.jpg', '{"id":"xishuipo","name":"西水坡遗址","city":"濮阳","era":"仰韶","type":"墓葬群","typeDesc":"仰韶文化墓葬群","dynasty":"仰韶文化中期（约6500年前）","cover":"🐲","image":"xishuipo.jpg","summary":"出土蚌塑“中华第一龙”的史前墓葬，龙图腾的祖源","intro":"西水坡遗址位于濮阳市西南，1987年考古发掘中，在仰韶文化中期墓葬M45内发现用蚌壳精心摆塑的龙、虎图案，龙长1.78米，昂首曲颈、状若腾飞，被誉为“中华第一龙”，将中华民族的龙图腾史向前推进至6500年前。遗址因此被称为“中华龙乡”濮阳的文化源头。","archaeology":"1987—1988年，濮阳西水坡遗址发掘出土仰韶文化墓葬、房址与蚌塑龙虎图案三组，其中M45墓主居中，东侧蚌塑龙、西侧蚌塑虎，其布局与后世四象观念渊源密切。蚌塑龙为中国迄今发现最早、形体最大的龙形象之一，是研究中国龙文化起源的顶级实物资料。","relics":[{"name":"中华第一龙（蚌塑龙）","desc":"距今六千余年，用蚌壳摆塑而成的龙形图案，形象生动，是中国早期龙图腾的重要实证。"},{"name":"蚌塑虎图案","desc":"与蚌塑龙同出，龙虎左右相对，被认为与早期天文、信仰和方位观念密切相关。"}],"events":[{"time":"1987年","title":"“中华第一龙”出土","desc":"西水坡遗址M45墓葬出土蚌塑龙虎图案，龙图腾史前实证问世。"},{"time":"2001年","title":"入选全国重点文物保护单位","desc":"西水坡遗址被国务院公布为第五批全国重点文物保护单位。"}],"poems":[{"title":"学界评语","author":"龙文化研究","content":"中华第一龙，六千年文明密码的蚌塑实证。"}],"tourism":{"address":"濮阳市华龙区西水坡（相关陈列见濮阳市戚城文物景区、濮阳市博物馆）","openTime":"以相关展馆公告为准","ticket":"以展馆公告为准","tips":"蚌塑龙虎图案真迹原件珍贵，展出以博物馆公告为准；濮阳被称为“中华龙乡”，春节“龙文化”活动丰富。"},"keywords":["中华第一龙","蚌塑","龙图腾","濮阳","仰韶文化"]}'),
('tieqiu', '铁丘遗址', '濮阳', '龙山', '古建筑', '龙山文化聚落遗址', '龙山文化时期（约4500—4000年前）', '濮阳境内见证龙山先民生活的黄河台地聚落', 'tieqiu.jpg', '{"id":"tieqiu","name":"铁丘遗址","city":"濮阳","era":"龙山","type":"古建筑","typeDesc":"龙山文化聚落遗址","dynasty":"龙山文化时期（约4500—4000年前）","cover":"⛰️","image":"tieqiu.jpg","summary":"濮阳境内见证龙山先民生活的黄河台地聚落","intro":"铁丘遗址位于濮阳市华龙区，地处黄河故道高台之上，是豫北地区一处重要的龙山文化时期聚落遗址。遗址文化层堆积深厚，出土陶器、石器、骨器及动物骨骼等遗物，反映4000多年前黄河中下游先民渔猎、农耕并举的生产生活方式，是研究濮阳地区早期历史的重要实物资料。","archaeology":"历次调查与试掘表明，遗址包含龙山文化至商周时期多个阶段遗存，采集到夹砂灰陶、磨光黑陶、篮纹陶片及石斧、石镰、蚌刀等生产工具，为复原黄河台地聚落的生业形态提供了依据。","relics":[{"name":"龙山文化陶鬲","desc":"三足炊器，龙山文化代表性器物，用于煮食，反映当时的日常生活与制陶工艺。"},{"name":"骨器与蚌器","desc":"遗址出土的骨锥、蚌刀等生产工具，是研究黄河下游龙山文化生业方式的重要材料。"}],"events":[{"time":"20世纪80年代","title":"考古调查确认","desc":"文物普查确认铁丘遗址的龙山文化性质与范围，列入文物保护名录。"}],"poems":[{"title":"学界评语","author":"濮阳考古研究","content":"铁丘台地之上，埋藏着黄河先民农耕与渔猎并行的古老记忆。"}],"tourism":{"address":"濮阳市华龙区（具体位置以文保部门公布为准）","openTime":"遗址现场，参观以当地文保部门安排为准","ticket":"无需门票","tips":"建议结合濮阳戚城遗址、西水坡遗址进行“濮阳史前—春秋”主题串联探访。"},"keywords":["龙山文化","聚落","濮阳","黄河故道","农耕"]}'),
('qicheng', '戚城遗址', '濮阳', '周', '都城遗址', '春秋卫国重要城邑', '春秋时期', '卫国故城与“戚城会盟”发生地，许穆夫人故国城邑', 'qicheng.jpg', '{"id":"qicheng","name":"戚城遗址","city":"濮阳","era":"周","type":"都城遗址","typeDesc":"春秋卫国重要城邑","dynasty":"春秋时期","cover":"🏯","image":"qicheng.jpg","summary":"卫国故城与“戚城会盟”发生地，许穆夫人故国城邑","intro":"戚城遗址位于濮阳市区，是春秋时期卫国的重要城邑，城垣平面近方形，至今仍有数米高夯土城墙耸立，为全国保存较好的东周城址之一。戚城曾多次作为诸侯会盟之地，史载“戚城之会”屡见于《春秋》；卫国诗《诗经·鄘风·载驰》即与卫国命运相关，作者许穆夫人是中国文学史上第一位女诗人。","archaeology":"遗址内外发现仰韶、龙山至汉代文化层，城墙夯层清晰可辨；城址内采集到春秋时期陶片、瓦当等遗物；2017年起在遗址内进行考古发掘，确认城址沿用年代与布局。戚城文物景区建有“戚城会盟”主题雕塑与濮阳卫国文化陈列。","relics":[{"name":"春秋城墙夯土","desc":"戚城遗址保存较好的春秋时期城垣夯土遗存，夯层清晰，是研究春秋卫国都城的重要实物。"},{"name":"春秋陶鬲与陶豆","desc":"出土的生活用陶器组合，鬲用于炊煮、豆用于盛食，反映当时的饮食与礼俗。"}],"events":[{"time":"春秋时期","title":"戚城会盟","desc":"戚城为诸侯会盟重地，见于《春秋》经传记载，见证春秋争霸风云。"},{"time":"1996年","title":"入选全国重点文物保护单位","desc":"戚城遗址被国务院公布为第四批全国重点文物保护单位。"}],"poems":[{"title":"《诗经·鄘风·载驰》","author":"许穆夫人","content":"载驰载驱，归唁卫侯。驱马悠悠，言至于漕。"}],"tourism":{"address":"濮阳市华龙区京开大道戚城文物景区","openTime":"周二至周日，具体以景区公告为准","ticket":"以景区公告为准","tips":"现存城墙可登临眺望；景区内的“中华第一龙”陈列与西水坡遗址可联游。"},"keywords":["卫国","戚城会盟","许穆夫人","濮阳","东周城址"]}'),
('yinxu', '殷墟', '安阳', '夏商', '都城遗址', '商代晚期都城遗址', '商代晚期（约3300年前）', '甲骨文发现地，中国历史上第一个有文献可考、为考古所证实的都城', 'yinxu.jpg', '{"id":"yinxu","name":"殷墟","city":"安阳","era":"夏商","type":"都城遗址","typeDesc":"商代晚期都城遗址","dynasty":"商代晚期（约3300年前）","cover":"🐉","image":"yinxu.jpg","summary":"甲骨文发现地，中国历史上第一个有文献可考、为考古所证实的都城","intro":"殷墟位于安阳市西北郊，是商代晚期都城遗址，距今约3300年，是中国历史上第一个有文献可考并为考古学和甲骨文所证实的都城遗址。1899年甲骨文的发现震惊世界，此后百年考古确认了宫殿宗庙区、王陵区、手工业作坊区与族邑聚落。2006年殷墟列入《世界遗产名录》，成为实证中华文明连续性的重要坐标。","archaeology":"1928年中央研究院历史语言研究所开始科学发掘，至今出土甲骨约15万片，发现单字4500余个；1976年妇好墓出土随葬品1928件，其中青铜器468件，包括著名的妇好鸮尊、司母辛鼎；殷墟王陵区发现大量祭祀坑与大型墓葬。殷墟博物馆新馆于2024年建成开放。","relics":[{"name":"后母戊鼎","desc":"商代晚期王室重器，是目前已知最大最重的青铜礼器，代表商代青铜文明的巅峰。"},{"name":"甲骨刻辞","desc":"商王占卜记事刻于龟甲兽骨之上，是已发现的成熟汉字体系最早样本，直接催生了甲骨学。"},{"name":"妇好墓玉凤","desc":"出自殷墟唯一保存完整的商代王室墓葬，玉质晶莹、线条流畅，反映商代高超的琢玉技艺。"}],"events":[{"time":"1899年","title":"甲骨文被发现","desc":"王懿荣首次辨认甲骨文，“一片甲骨惊天下”，开启中国古文字学新纪元。"},{"time":"1928年","title":"首次科学考古发掘","desc":"中央研究院历史语言研究所对殷墟进行首次科学发掘，中国考古学由此走向成熟。"},{"time":"2006年","title":"列入世界文化遗产","desc":"殷墟被联合国教科文组织列入《世界遗产名录》。"}],"poems":[{"title":"《访安阳殷墟》","author":"郭沫若","content":"洹水安阳名不虚，三千年前是帝都。"}],"tourism":{"address":"安阳市殷都区殷墟博物馆（殷墟宫殿宗庙遗址、王陵遗址）","openTime":"周二至周日，具体以博物馆公告为准","ticket":"以博物馆公告为准","tips":"妇好墓、甲骨窖穴（YH127）、车马坑陈列是必看内容；建议预留半天以上。"},"keywords":["甲骨文","妇好墓","世界文化遗产","安阳","商代晚期"]}'),
('miaodigou', '庙底沟遗址', '三门峡', '仰韶', '古建筑', '仰韶文化中心聚落', '新石器时代仰韶文化中晚期（约6000—5300年前）', '仰韶文化庙底沟类型的命名地，彩陶文化影响遍及大半个中国', 'miaodigou.jpg', '{"id":"miaodigou","name":"庙底沟遗址","city":"三门峡","era":"仰韶","type":"古建筑","typeDesc":"仰韶文化中心聚落","dynasty":"新石器时代仰韶文化中晚期（约6000—5300年前）","cover":"🏺","image":"miaodigou.jpg","summary":"仰韶文化庙底沟类型的命名地，彩陶文化影响遍及大半个中国","intro":"庙底沟遗址位于三门峡市陕州区，是仰韶文化中期最具代表性的中心聚落之一。1956—1957年首次发掘，发现房址、灰坑、窑址及大量彩陶。以庙底沟遗址为代表的彩陶纹样——花瓣纹、鸟纹、太阳纹等风格独特，仰韶文化中期因此命名为「庙底沟类型」。其彩陶文化向外辐射，西至甘肃、青海，东到河南东部，是史前中华文化圈形成的关键阶段。","archaeology":"1956年黄河水库考古工作队首次发掘。第五批全国重点文物保护单位（2001）。2021年入选「百年百大考古发现」。","relics":[{"name":"彩陶花瓣纹盆","desc":"庙底沟类型最具代表性的彩陶之一，黑彩花瓣纹繁密而规整。"}],"events":[{"time":"1956年","title":"首次考古发掘","desc":"黄河水库考古工作队首次发掘，确立「庙底沟类型」命名。"}],"poems":[{"title":"考古学界评价","author":"学界共识","content":"庙底沟彩陶是史前中华文化圈的第一张名片。"}],"tourism":{"address":"三门峡市陕州区庙底沟村","openTime":"以景区公告为准","ticket":"以景区公告为准","tips":"可与庙底沟仰韶文化博物馆联游。"},"keywords":["彩陶","庙底沟","仰韶文化","史前聚落","河南"]}'),
('beiyangping', '北阳平遗址群', '三门峡', '仰韶', '都城遗址', '仰韶大型中心聚落群', '仰韶文化中期（约6000—5300年前）', '仰韶庙底沟时期最大的中心聚落群，含西坡遗址等50余处', 'beiyangping.jpg', '{"id":"beiyangping","name":"北阳平遗址群","city":"三门峡","era":"仰韶","type":"都城遗址","typeDesc":"仰韶大型中心聚落群","dynasty":"仰韶文化中期（约6000—5300年前）","cover":"🏛️","image":"beiyangping.jpg","summary":"仰韶庙底沟时期最大的中心聚落群，含西坡遗址等50余处","intro":"北阳平遗址群位于灵宝市铸鼎塬上，是仰韶庙底沟时期规模最大的中心聚落集群，包含北阳平、西坡、东常、轩辕台等50余处遗址点，总面积达40余平方公里。其中西坡遗址发掘出面积达516平方米的特大型半地穴式房址（F105），被学界称为「华夏第一宫殿」。铸鼎塬因传说中黄帝在此铸鼎而得名，北阳平遗址群为中华文明起源研究提供了关键实证。","archaeology":"2000—2006年中国社科院考古所等联合发掘。第五批全国重点文物保护单位（2001）。西坡遗址列入中华文明探源工程六大首选遗址。","relics":[{"name":"西坡F105大型房基","desc":"仰韶文化规模最大的单体建筑基址之一，面积约516平方米。"}],"events":[{"time":"2001年","title":"第五批全国重点文物保护单位","desc":"北阳平遗址群被国务院公布为第五批国保。"}],"poems":[{"title":"铸鼎塬怀古","author":"考古学界","content":"铸鼎塬上华夏魂，五千年前见宫阙。"}],"tourism":{"address":"三门峡市灵宝市阳平镇铸鼎塬","openTime":"以景区公告为准","ticket":"以景区公告为准","tips":"可与黄帝铸鼎塬文化园、西坡遗址联游。"},"keywords":["西坡","铸鼎塬","华夏第一宫殿","探源工程","史前城址"]}'),
('guoshangyang', '虢都上阳城', '三门峡', '周', '都城遗址', '西周至春秋虢国都城', '西周晚期至春秋早期', '西周至春秋时期虢国（上阳虢）都城，前655年「假虞灭虢」后亡', 'guoshangyang.jpg', '{"id":"guoshangyang","name":"虢都上阳城","city":"三门峡","era":"周","type":"都城遗址","typeDesc":"西周至春秋虢国都城","dynasty":"西周晚期至春秋早期","cover":"🏛️","image":"guoshangyang.jpg","summary":"西周至春秋时期虢国（上阳虢）都城，前655年「假虞灭虢」后亡","intro":"虢都上阳城位于三门峡市陕州区，是西周晚期至春秋早期虢国（上阳虢，姬姓）的都城。城址于2000年经考古发掘确认，面积约32万平方米，发现完整的城垣、城壕、宫城与宫殿区。公元前655年晋国「假虞灭虢」，虢国灭亡。与上村岭虢国墓地同属虢国文化遗存，为研究西周分封制与诸侯国都城提供了宝贵实物。","archaeology":"2000年发掘确认城垣与宫殿区。1963年河南省第一批文物保护单位。","relics":[{"name":"虢都上阳城垣","desc":"西周至春秋时期虢国都城遗存，夯土筑造，城垣、城壕保存较好。"}],"events":[{"time":"前655年","title":"假虞灭虢","desc":"晋国借道虞国攻虢，灭虢后顺手灭虞，上阳城成为晋军占领地。"}],"poems":[{"title":"考古学界评价","author":"学界共识","content":"虢国都城与墓地相距仅2公里，构成完整的诸侯国都城体系。"}],"tourism":{"address":"三门峡市陕州区青龙涧河北岸","openTime":"以景区公告为准","ticket":"以景区公告为准","tips":"可与虢国博物馆联游。"},"keywords":["虢国","上阳城","假虞灭虢","西周","春秋"]}'),
('baolinsi', '宝轮寺塔', '三门峡', '宋', '古建筑', '金代密檐式砖塔（俗称蛤蟆塔）', '金大定十七年（1177）重建', '中国古代四大回音建筑之一，俗称「蛤蟆塔」', 'baolinsi.jpg', '{"id":"baolinsi","name":"宝轮寺塔","city":"三门峡","era":"宋","type":"古建筑","typeDesc":"金代密檐式砖塔（俗称蛤蟆塔）","dynasty":"金大定十七年（1177）重建","cover":"🗼","image":"baolinsi.jpg","summary":"中国古代四大回音建筑之一，俗称「蛤蟆塔」","intro":"宝轮寺塔位于三门峡市陕州区，寺院为唐代创建，现存塔为金大定十七年（1177）重建。塔高26.5米，方形十三级密檐式砖塔，是中国古代四大回音建筑之一（与北京天坛回音壁、四川潼南石琴、山西永济普救寺莺莺塔并称）。人在塔周击掌，塔内发出呱呱之声，形似蛤蟆鸣叫，故俗称「蛤蟆塔」。","archaeology":"第五批全国重点文物保护单位（2001）。塔内现存金大定十七年石碣记载重建始末。","relics":[{"name":"金代密檐式砖塔","desc":"宝轮寺塔塔身，金大定十七年重建遗构，方形十三级，密檐式砖塔。"}],"events":[{"time":"1177年","title":"金代重建","desc":"金大定十七年（1177）重建宝轮寺塔，现存塔身即为此次重建遗构。"}],"poems":[{"title":"陕州蛤蟆塔","author":"民间传说","content":"手拍塔身呱呱响，形似蛤蟆叫不停。金代古塔八百载，回音奇迹誉九州。"}],"tourism":{"address":"三门峡市陕州区老城东南角","openTime":"以景区公告为准","ticket":"以景区公告为准","tips":"可与陕州地坑院联游。"},"keywords":["回音建筑","蛤蟆塔","金代","四大回音"]}'),
('xiaohanpath', '崤函古道石壕段', '三门峡', '宋', '古建筑', '唐宋古道遗存（丝绸之路遗产点）', '唐宋（沿用至明清）', '丝绸之路河南段唯一保存完好的古代道路遗存，2014年列入世界遗产', 'xiaohanpath.jpg', '{"id":"xiaohanpath","name":"崤函古道石壕段","city":"三门峡","era":"宋","type":"古建筑","typeDesc":"唐宋古道遗存（丝绸之路遗产点）","dynasty":"唐宋（沿用至明清）","cover":"🛤️","image":"xiaohanpath.jpg","summary":"丝绸之路河南段唯一保存完好的古代道路遗存，2014年列入世界遗产","intro":"崤函古道石壕段位于三门峡市陕州区硖石乡车壕村，是古代连接中原与关中的东西大道——崤函古道的一段，也是唐代大诗人杜甫《石壕吏》诗中「石壕村」的所在地。现存遗迹为长约100余米的石板路面，上车辙印痕清晰保存，辙宽约1.06米，车辙间距约2.4米。2014年作为「丝绸之路：长安—天山廊道」遗产点列入世界文化遗产，是三门峡市唯一的世界文化遗产点。","archaeology":"第八批全国重点文物保护单位（2019）；2014年列入世界文化遗产。","relics":[{"name":"古代车辙印痕","desc":"石板路面上清晰保留的古代车辆车辙痕迹，辙宽1.06米，为研究古代交通提供直接证据。"}],"events":[{"time":"2014年","title":"列入世界文化遗产","desc":"作为丝绸之路遗产点列入世界遗产名录。"}],"poems":[{"title":"杜甫《石壕吏》","author":"杜甫","content":"暮投石壕村，有吏夜捉人。（石壕村即古道旁村落）"}],"tourism":{"address":"三门峡市陕州区硖石乡车壕村","openTime":"以景区公告为准","ticket":"以景区公告为准","tips":"可与硖石乡古镇联游。"},"keywords":["丝绸之路","世界遗产","崤函古道","石壕吏","唐宋"]}')
INSERT INTO heritage_site (id, name, city, era, type, type_desc, dynasty, summary, image, detail_json) VALUES
('luoyangzhouwangcheng', '洛阳东周王城', '洛阳', '周', '都城遗址', '东周都城', '东周（前770—前5世纪）', '东周（平王东迁至周赧王）都城，发现「天子驾六」车马坑', 'luoyangzhouwangcheng.jpg', '{"id":"luoyangzhouwangcheng","name":"洛阳东周王城","city":"洛阳","era":"周","type":"都城遗址","typeDesc":"东周都城","dynasty":"东周（前770—前5世纪）","cover":"🏛️","image":"luoyangzhouwangcheng.jpg","summary":"东周（平王东迁至周赧王）都城，发现「天子驾六」车马坑","intro":"洛阳东周王城位于洛阳市西工区涧河两岸，是公元前770年周平王东迁洛邑后所建都城，历经东周500余年。遗址面积约5平方公里，发现完整的城垣、宫殿区、手工作坊区与墓葬区。2002年在王城广场发现「天子驾六」大型车马坑——天子乘六匹马驾的马车出土，与《周礼》记载吻合，震惊考古界。","archaeology":"第七批全国重点文物保护单位（2013）。2002年发现「天子驾六」车马坑群，同年建立天子驾六博物馆。","relics":[{"name":"天子驾六车马坑","desc":"出土六马一车的周天子级车马遗存，佐证《周礼》「天子驾六」记载。"}],"events":[{"time":"前770年","title":"平王东迁","desc":"周平王东迁洛邑，建立东周王城，开启东周时代。"}],"poems":[{"title":"东周怀古","author":"唐代","content":"洛川波暖柳含烟，东周遗都六百年。涧河两岸埋王者，驾六车马纪当年。"}],"tourism":{"address":"洛阳市西工区王城广场","openTime":"天子驾六博物馆：周二至周日","ticket":"以景区公告为准","tips":"可近距离观摩车马坑现场。"},"keywords":["东周","天子驾六","平王东迁","车马坑"]}'),
('mangshanlingqun', '邙山陵墓群', '洛阳', '汉唐', '墓葬群', '东周至北魏六代帝王陵及陪葬墓群', '东周—北魏（含东汉、曹魏、西晋、北魏、五代后唐）', '有「东方金字塔」之称，六代24座帝王陵及陪葬墓群', 'mangshanlingqun.jpg', '{"id":"mangshanlingqun","name":"邙山陵墓群","city":"洛阳","era":"汉唐","type":"墓葬群","typeDesc":"东周至北魏六代帝王陵及陪葬墓群","dynasty":"东周—北魏（含东汉、曹魏、西晋、北魏、五代后唐）","cover":"⚰️","image":"mangshanlingqun.jpg","summary":"有「东方金字塔」之称，六代24座帝王陵及陪葬墓群","intro":"邙山陵墓群分布于洛阳北部邙山上，是中国已知规模最大、年代延续时间最长的帝王陵墓群之一。已确认东周、东汉、曹魏、西晋、北魏、五代后唐6代共24座帝王陵及大量陪葬墓，总面积达756平方公里。其中东汉帝陵分邙山（北兆域）与洛南（南兆域）两大区域，北魏帝陵集中于孟津邙岭之上。邙山因「生在苏杭，葬在北邙」之说而闻名天下。","archaeology":"第五批全国重点文物保护单位（2001）。","relics":[{"name":"北魏宣武帝景陵","desc":"邙山北魏帝陵之一，已考古发掘，是研究北魏帝陵规制的重要实例。"}],"events":[{"time":"2001年","title":"第五批全国重点文物保护单位","desc":"邙山陵墓群以整体项目列入第五批国保。"}],"poems":[{"title":"北邙行","author":"王建（唐）","content":"北邙山头少闲土，尽是洛阳人旧墓。"}],"tourism":{"address":"洛阳市北部邙山（横跨多区县）","openTime":"以各陵区公告为准","ticket":"以景区公告为准","tips":"可与洛阳邙山博物馆、汉魏洛阳故城联游。"},"keywords":["东方金字塔","帝陵","东汉","曹魏","西晋","北魏","邙山"]}'),
('guanlin', '关林', '洛阳', '宋', '古建筑', '关羽葬首祠庙（传说）', '东汉始葬说；现存建筑明清', '传说关羽葬首处，祠庙与墓冢合一的三国文化圣地', 'guanlin.jpg', '{"id":"guanlin","name":"关林","city":"洛阳","era":"宋","type":"古建筑","typeDesc":"关羽葬首祠庙（传说）","dynasty":"东汉始葬说；现存建筑明清","cover":"🏯","image":"guanlin.jpg","summary":"传说关羽葬首处，祠庙与墓冢合一的三国文化圣地","intro":"关林位于洛阳市洛龙区关林镇，传为三国时期关羽被东吴所害后，孙权将其首级送给曹操，曹操以诸侯礼葬于此地。现存建筑多为明清重建，占地约180亩。关冢高约20米，埋葬关羽头颅（相传）。与山西解州关帝庙、湖北当阳关帝陵并称「中国三大关帝庙」。第六批全国重点文物保护单位（2006）。","archaeology":"第六批全国重点文物保护单位（2006）。墓冢年代无考古确证，现存为明清祠庙建筑群。","relics":[{"name":"明代铁狮","desc":"关林大门前明代铸造的铁狮，铸工精细，反映明代祠庙建筑装饰工艺。"}],"events":[{"time":"2006年","title":"第六批全国重点文物保护单位","desc":"关林以「古建筑」类列入第六批国保。"}],"poems":[{"title":"关林","author":"清代","content":"汉寿亭侯墓，春秋大义传。英雄无复见，庙貌尚巍然。"}],"tourism":{"address":"洛阳市洛龙区关林镇","openTime":"全年开放","ticket":"以景区公告为准","tips":"可与龙门石窟、白园联游。"},"keywords":["关羽","关帝","三国","关林庙会"]}'),
('fengxianguan', '奉仙观', '济源', '汉唐', '古建筑', '金代道教宫观', '唐垂拱元年（685）创建；金大定二十四年（1184）重建三清大殿', '俗称「荆梁观」，金代木构建筑减柱造「三绝」闻名全国', 'fengxianguan.jpg', '{"id":"fengxianguan","name":"奉仙观","city":"济源","era":"汉唐","type":"古建筑","typeDesc":"金代道教宫观","dynasty":"唐垂拱元年（685）创建；金大定二十四年（1184）重建三清大殿","cover":"🏯","image":"fengxianguan.jpg","summary":"俗称「荆梁观」，金代木构建筑减柱造「三绝」闻名全国","intro":"奉仙观位于济源市区，始建于唐垂拱元年（685），三清大殿为金大定二十四年（1184）重建。大殿以「减柱造」手法仅用两根粗大的荆根柿木梁承重，八根柱子减为六根，俗称「荆梁观」。奉仙观三大建筑奇迹：荆根柿木梁、石柱神异图案、金代建筑工艺。第五批全国重点文物保护单位（2001）。","archaeology":"第五批全国重点文物保护单位（2001）。","relics":[{"name":"荆根柿木梁","desc":"金代三清大殿承重梁，由荆条根连同柿木构成，自然弯曲成形，为奉仙观「三绝」之一。"}],"events":[{"time":"2001年","title":"第五批全国重点文物保护单位","desc":"奉仙观被国务院公布为第五批全国重点文物保护单位。"}],"poems":[{"title":"奉仙观","author":"清代","content":"古观巍巍荆梁观，金代遗构近千年。减柱造法惊天下，两根巨梁撑殿堂。"}],"tourism":{"address":"济源市荆梁街奉仙观街","openTime":"以景区公告为准","ticket":"以景区公告为准","tips":"可与济渎庙、大明寺联游。"},"keywords":["荆梁观","减柱造","金代木构","道教宫观"]}'),
('yewanggong', '阳台宫', '济源', '汉唐', '古建筑', '明代道教宫观（王屋山三宫之一）', '唐开元十二年（724）创建；现存主体明清', '河南现存规模最大的明代木构殿堂之一', 'yewanggong.jpg', '{"id":"yewanggong","name":"阳台宫","city":"济源","era":"汉唐","type":"古建筑","typeDesc":"明代道教宫观（王屋山三宫之一）","dynasty":"唐开元十二年（724）创建；现存主体明清","cover":"🏯","image":"yewanggong.jpg","summary":"河南现存规模最大的明代木构殿堂之一","intro":"阳台宫位于济源市王屋山华盖峰南麓，是唐代著名道士司马承祯修道之所。唐开元十二年（724）唐玄宗敕令创建。现存主体为明清建筑，三清大殿面阔五间、进深四间，单檐歇山顶，是河南现存规模最大的明代木构殿堂之一。王屋山道教「三宫」之一。第六批全国重点文物保护单位（2006）。","archaeology":"第六批全国重点文物保护单位（2006）。","relics":[{"name":"明代三清大殿","desc":"阳台宫主殿，面阔五间、进深四间，单檐歇山顶，是河南明代木构殿堂代表。"}],"events":[{"time":"2006年","title":"第六批全国重点文物保护单位","desc":"阳台宫被国务院公布为第六批全国重点文物保护单位。"}],"poems":[{"title":"阳台宫","author":"唐代","content":"王屋山中阳台宫，玄宗敕建至今崇。三清大殿云中立，恍见司马修道踪。"}],"tourism":{"address":"济源市王屋山华盖峰南麓","openTime":"以景区公告为准","ticket":"以景区公告为准","tips":"位于王屋山景区内。"},"keywords":["道教","王屋山","司马承祯","明代木构"]}'),
('jiayingguan', '嘉应观', '焦作', '宋', '古建筑', '清代河神庙（黄河小故宫）', '清雍正元年（1723）敕建', '仿北京故宫布局，有「黄河小故宫」「万里黄河第一观」之誉', 'jiayingguan.jpg', '{"id":"jiayingguan","name":"嘉应观","city":"焦作","era":"宋","type":"古建筑","typeDesc":"清代河神庙（黄河小故宫）","dynasty":"清雍正元年（1723）敕建","cover":"🏯","image":"jiayingguan.jpg","summary":"仿北京故宫布局，有「黄河小故宫」「万里黄河第一观」之誉","intro":"嘉应观位于焦作市武陟县，是清雍正元年（1723）雍正帝为祭祀黄河河神而敕建，仿北京故宫布局。集宫、庙、衙署于一体，规模宏大、等级最高，故有「黄河小故宫」「万里黄河第一观」之誉。观内雍正撰文的铜碑为珍贵遗存。第五批全国重点文物保护单位（2001）。","archaeology":"第五批全国重点文物保护单位（2001）。","relics":[{"name":"雍正铜碑","desc":"雍正撰文的《嘉应观御制碑》，铜质，记载建观缘由。"}],"events":[{"time":"1723年","title":"雍正敕建嘉应观","desc":"清雍正元年（1723）雍正帝敕建嘉应观，成为全国规格最高的河神庙。"}],"poems":[{"title":"嘉应观","author":"清代","content":"万里黄河第一观，雍正敕建比皇官。河神金龙四大王，护佑中原岁岁安。"}],"tourism":{"address":"焦作市武陟县嘉应观乡","openTime":"全年开放","ticket":"以景区公告为准","tips":"可与武陟妙乐寺塔联游。"},"keywords":["黄河小故宫","雍正","河神庙","治黄史","武陟"]}'),
('handyemiao', '韩愈墓（韩园）', '焦作', '汉唐', '墓葬群', '唐代文学家韩愈墓', '唐（韩愈墓）', '唐代「文起八代之衰」的韩愈之墓', 'handyemiao.jpg', '{"id":"handyemiao","name":"韩愈墓（韩园）","city":"焦作","era":"汉唐","type":"墓葬群","typeDesc":"唐代文学家韩愈墓","dynasty":"唐（韩愈墓）","cover":"⚰️","image":"handyemiao.jpg","summary":"唐代「文起八代之衰」的韩愈之墓","intro":"韩愈墓位于焦作市孟州市韩家庄，是唐代著名文学家、思想家韩愈的墓地。韩愈（768—824），字退之，世称「韩昌黎」，唐代古文运动领袖，与柳宗元并称「韩柳」，位列「唐宋八大家」之首。第六批全国重点文物保护单位（2006）。","archaeology":"第六批全国重点文物保护单位（2006）。","relics":[{"name":"韩愈墓明代墓碑","desc":"韩园墓前的明代重立墓碑，记载韩愈生平与墓冢沿革。"}],"events":[{"time":"2006年","title":"第六批全国重点文物保护单位","desc":"韩愈墓以「古墓葬」类列入第六批国保。"}],"poems":[{"title":"韩园怀古","author":"清代","content":"文起八代韩愈公，韩园千载祭遗风。道济天下文载道，唐宋八家列首功。"}],"tourism":{"address":"焦作市孟州市西虢镇韩家庄","openTime":"以景区公告为准","ticket":"以景区公告为准","tips":"可与孟州慈胜寺联游。"},"keywords":["韩愈","唐宋八大家","古文运动","孟州"]}'),
('wangchenggang', '王城岗及阳城遗址', '郑州', '龙山', '都城遗址', '龙山晚期城址（禹都阳城）+ 战国韩阳城', '新石器时代晚期（龙山）—东周', '龙山晚期城址，主流倾向即「禹都阳城」', 'wangchenggang.jpg', '{"id":"wangchenggang","name":"王城岗及阳城遗址","city":"郑州","era":"龙山","type":"都城遗址","typeDesc":"龙山晚期城址（禹都阳城）+ 战国韩阳城","dynasty":"新石器时代晚期（龙山）—东周","cover":"🏛️","image":"wangchenggang.jpg","summary":"龙山晚期城址，主流倾向即「禹都阳城」","intro":"王城岗及阳城遗址位于郑州市登封市告成镇，是龙山晚期城址与东周阳城城址的叠加。王城岗龙山晚期大城总面积约34.8万平方米，出土城垣、壕沟、宫殿灰坑及珍贵的陶刻符号，被学界主流倾向为「禹都阳城」。东周阳城则为战国韩国重要城邑。第四批全国重点文物保护单位（1996）。","archaeology":"第四批全国重点文物保护单位（1996）。2002—2005年中华文明探源工程再次发掘。","relics":[{"name":"龙山陶刻符号","desc":"王城岗遗址出土的龙山陶片刻划符号，被部分学者视为「原始文字」。"}],"events":[{"time":"前20世纪","title":"传说禹都阳城","desc":"文献记载「禹都阳城」，主流倾向与王城岗龙山晚期大城对应。"}],"poems":[{"title":"告成怀古","author":"学界","content":"夏都阳城探源地，王城岗下见陶文。四千年时如转瞬，中原文明续至今。"}],"tourism":{"address":"郑州市登封市告成镇","openTime":"以景区公告为准","ticket":"以景区公告为准","tips":"可与登封观星台、嵩岳寺塔联游。"},"keywords":["禹都","夏文化","探源工程","登封","阳城"]}'),
('songling', '宋陵（北宋皇陵）', '郑州', '宋', '墓葬群', '北宋「七帝八陵」及祔葬墓群', '北宋（960—1127）', '北宋「七帝八陵」，面积达180平方公里的石雕博物馆', 'songling.jpg', '{"id":"songling","name":"宋陵（北宋皇陵）","city":"郑州","era":"宋","type":"墓葬群","typeDesc":"北宋「七帝八陵」及祔葬墓群","dynasty":"北宋（960—1127）","cover":"⚰️","image":"songling.jpg","summary":"北宋「七帝八陵」，面积达180平方公里的石雕博物馆","intro":"宋陵即北宋皇陵，位于郑州市巩义市，是北宋「七帝八陵」的统称——太祖永昌陵、太宗永熙陵、真宗永定陵、仁宗永昭陵、英宗永厚陵、神宗永裕陵、哲宗永泰陵，以及宣祖永安陵（赵匡胤之父）。祔葬后妃、宗室、功臣约300余座。总面积约180平方公里，保存石刻约1027件，被誉为「大地上的露天石雕博物馆」。第二全国重点文物保护单位（1982）。","archaeology":"第二批全国重点文物保护单位（1982）。永昭陵（宋陵公园）已复原。","relics":[{"name":"北宋陵前石象生","desc":"宋陵各帝陵前的石象生群，雕刻精美，反映北宋石雕艺术巅峰。"}],"events":[{"time":"976年","title":"太祖永昌陵始建","desc":"北宋建国后，宋太祖即开始营建永昌陵，开启宋陵160余年营造史。"}],"poems":[{"title":"宋陵怀古","author":"元代","content":"七帝八陵巩洛间，石雕千件立千年。靖康之耻家国恨，空留残碑对夕阳。"}],"tourism":{"address":"郑州市巩义市市区及西村镇一带","openTime":"以景区公告为准","ticket":"以景区公告为准","tips":"可与巩义黄冶三彩窑址、康百万庄园联游。永昭陵距市区最近。"},"keywords":["北宋皇陵","七帝八陵","宋代石雕","巩义"]}'),
('shaolinsi', '少林寺', '郑州', '汉唐', '古建筑', '禅宗祖庭、武术圣地', '唐至清（现存主体明清）', '禅宗祖庭、天下武功出少林，2010年列入世界文化遗产', 'shaolinsi.jpg', '{"id":"shaolinsi","name":"少林寺","city":"郑州","era":"汉唐","type":"古建筑","typeDesc":"禅宗祖庭、武术圣地","dynasty":"唐至清（现存主体明清）","cover":"🏯","image":"shaolinsi.jpg","summary":"禅宗祖庭、天下武功出少林，2010年列入世界文化遗产","intro":"少林寺位于郑州市登封市嵩山少室山五乳峰下，是佛教禅宗祖庭和少林武术发源地。始建于北魏太和十九年（495），孝文帝为印度僧人跋陀所建。后来菩提达摩来到少林寺，面壁九年，开创禅宗，同时被尊为少林武术之祖。塔林是少林寺历代和尚墓塔群，为中国现存规模最大的墓塔建筑群。2010年作为「登封天地之中」世界文化遗产的一部分列入世界遗产名录。","archaeology":"第七批全国重点文物保护单位（2013）；2010年列入世界文化遗产。","relics":[{"name":"少林寺塔林","desc":"少林寺历代高僧墓塔群，现存唐至清墓塔228座，中国规模最大的墓塔群。"}],"events":[{"time":"495年","title":"少林寺创建","desc":"北魏太和十九年（495）孝文帝为印度僧人跋陀建寺。"},{"time":"2010年","title":"列入世界文化遗产","desc":"少林寺建筑群作为「登封天地之中」的核心组成部分列入世界遗产名录。"}],"poems":[{"title":"少林寺","author":"清代","content":"天下武功出少林，禅宗祖庭在此寻。塔林森森埋高僧，面壁九年见达摩。"}],"tourism":{"address":"郑州市登封市嵩山少室山五乳峰下","openTime":"全年开放","ticket":"以景区公告为准","tips":"可与嵩岳寺塔、观星台、中岳庙联游。"},"keywords":["禅宗","少林武术","世界遗产","嵩山","塔林"]}'),
('muyangta', '登封窑遗址', '郑州', '宋', '窑址', '唐宋民间瓷窑', '唐始烧，北宋兴盛', '以珍珠地划花著称的唐宋瓷窑，国家级非遗', 'muyangta.jpg', '{"id":"muyangta","name":"登封窑遗址","city":"郑州","era":"宋","type":"窑址","typeDesc":"唐宋民间瓷窑","dynasty":"唐始烧，北宋兴盛","cover":"🏺","image":"muyangta.jpg","summary":"以珍珠地划花著称的唐宋瓷窑，国家级非遗","intro":"登封窑遗址（亦称「曲河窑」）位于郑州市登封市告成镇曲河村，是唐宋时期著名民间瓷窑。产品以白釉珍珠地划花为最具特色——在器胎上施化妆土后，用尖状工具划出图案轮廓，在图案内填上细密的珍珠状圆点，最后施透明釉烧制。登封窑烧制技艺已列为国家级非物质文化遗产。","archaeology":"第二批河南省重点文物保护单位（1986）；登封窑烧制技艺为国家级非遗。","relics":[{"name":"珍珠地划花枕","desc":"登封窑最具代表性的产品，白釉划花，珍珠状圆点装饰。"}],"events":[{"time":"北宋","title":"珍珠地划花兴盛","desc":"北宋时期登封窑珍珠地划花工艺成熟，曾少量贡瓷。"}],"poems":[{"title":"登封窑","author":"清代","content":"珍珠地上写春秋，曲河窑火唐宋流。白釉划花成绝技，民间窑口亦风流。"}],"tourism":{"address":"郑州市登封市告成镇曲河村","openTime":"以景区公告为准","ticket":"以景区公告为准","tips":"可与登封王城岗、观星台联游。"},"keywords":["珍珠地划花","登封窑","曲河窑","国家级非遗"]}'),
('lujianwang', '潞简王墓', '新乡', '宋', '墓葬群', '明代藩王陵墓（全国最大）', '明万历年间（建成于1615年）', '我国现存规模最大、保存最完整的明代藩王陵墓', 'lujianwang.jpg', '{"id":"lujianwang","name":"潞简王墓","city":"新乡","era":"宋","type":"墓葬群","typeDesc":"明代藩王陵墓（全国最大）","dynasty":"明万历年间（建成于1615年）","cover":"⚰️","image":"lujianwang.jpg","summary":"我国现存规模最大、保存最完整的明代藩王陵墓","intro":"潞简王墓位于新乡市凤泉区凤凰山，是明代潞简王朱翊镠（明穆宗第四子、万历帝同母弟）及其次妃赵氏的墓地。建成于万历四十三年（1615），占地约400亩，是我国现存规模最大、保存最完整的明代藩王陵墓。陵区由神道、石刻仪仗、外城、内城、宝城、地宫等构成，规格之高堪与北京明十三陵媲美，被誉为「中原定陵」「豫北十三陵」。第四批全国重点文物保护单位（1996）。","archaeology":"第四批全国重点文物保护单位（1996）。次妃赵氏墓已考古发掘。","relics":[{"name":"潞简王墓石刻仪仗","desc":"墓道两侧的石人、石马、石象等，形制巨大、雕工精湛。"}],"events":[{"time":"1615年","title":"潞简王墓建成","desc":"明万历四十三年（1615）潞简王墓建成。"}],"poems":[{"title":"潞王陵","author":"清代","content":"凤凰山麓潞王陵，定陵规模藩王身。神道森森立石像，中原十三陵之誉。"}],"tourism":{"address":"新乡市凤泉区凤凰山","openTime":"全年开放","ticket":"以景区公告为准","tips":"可与比干庙、卫辉望京楼联游。"},"keywords":["明代藩王墓","中原定陵","凤凰山","朱翊镠"]}'),
('fantai', '繁塔', '开封', '宋', '古建筑', '北宋四角向八角过渡的佛塔', '北宋开宝七年（974）', '开封现存最古老建筑，四角塔向八角塔过渡的罕见实例', 'fantai.jpg', '{"id":"fantai","name":"繁塔","city":"开封","era":"宋","type":"古建筑","typeDesc":"北宋四角向八角过渡的佛塔","dynasty":"北宋开宝七年（974）","cover":"🗼","image":"fantai.jpg","summary":"开封现存最古老建筑，四角塔向八角塔过渡的罕见实例","intro":"繁塔（原名兴慈塔，因建于天清寺内亦称天清寺塔）位于开封市禹王台公园西南，是北宋开封城东南角的标志性建筑。建于北宋开宝七年（974），是开封现存最古老的建筑。繁塔为方形三层楼阁式砖塔，通高31.67米，底层四角、上层为六角，是中国四角塔向八角塔过渡的罕见实例。塔内外壁镶嵌佛像砖约7000块。第三批全国重点文物保护单位（1988）。","archaeology":"第三批全国重点文物保护单位（1988）。","relics":[{"name":"佛造像砖","desc":"繁塔内外壁镶嵌的7000余块佛像砖，造型各异。"}],"events":[{"time":"974年","title":"繁塔建成","desc":"北宋开宝七年（974）天清寺兴慈塔（繁塔）建成，为北宋东京城地标。"}],"poems":[{"title":"繁塔","author":"宋代","content":"开封铁塔与繁塔，南北对峙宋时家。四角八角过渡样，造型独特世间稀。"}],"tourism":{"address":"开封市禹王台公园西南侧","openTime":"以景区公告为准","ticket":"以景区公告为准","tips":"可与禹王台、相国寺联游。"},"keywords":["北宋佛塔","四角塔","天清寺","开封"]}'),
('kaifengcitywall', '开封城墙', '开封', '宋', '古建筑', '明清代城垣', '明—清（现存城垣）', '国内现存仅次于南京的第二大古代城垣', 'kaifengcitywall.jpg', '{"id":"kaifengcitywall","name":"开封城墙","city":"开封","era":"宋","type":"古建筑","typeDesc":"明清代城垣","dynasty":"明—清（现存城垣）","cover":"🏯","image":"kaifengcitywall.jpg","summary":"国内现存仅次于南京的第二大古代城垣","intro":"开封城墙是国内现存仅次于南京的第二大古代城垣。始建于唐代，五代、北宋、金、明、清历代多次修筑。现存城垣为明代洪武年间修筑，全长约14.4公里，城内面积约5.3平方公里。大梁门附近经考古发掘发现多层叠压的古代马道——战国大梁城、五代汴州城、北宋东京城、金南京城等，是中国古都「城摞城」奇观的典型代表。第三批全国重点文物保护单位（1996）。","archaeology":"第三批全国重点文物保护单位（1996）。大梁门附近证实「城摞城」。","relics":[{"name":"大梁门古马道遗址","desc":"大梁门地下发现多层叠压的古代马道，直观展示开封「城摞城」奇观。"}],"events":[{"time":"1379年","title":"明代修筑城墙","desc":"明洪武十二年（1379）修筑开封城墙，奠定今日格局。"}],"poems":[{"title":"开封城墙","author":"清代","content":"十三公里古城垣，城下层层叠旧年。城摞城中奇天下，大梁门里见古马。"}],"tourism":{"address":"开封市城区四周","openTime":"大梁门段以景区公告为准","ticket":"以景区公告为准","tips":"大梁门可登城墙、参观古马道遗址博物馆。"},"keywords":["城摞城","明代城垣","大梁门","古马道"]}'),
('gaocheng', '高城遗址', '濮阳', '周', '都城遗址', '东周卫国都城（帝丘）', '春秋—战国（卫）', '卫成公迁都帝丘，卫国都城凡388年所在地', 'gaocheng.jpg', '{"id":"gaocheng","name":"高城遗址","city":"濮阳","era":"周","type":"都城遗址","typeDesc":"东周卫国都城（帝丘）","dynasty":"春秋—战国（卫）","cover":"🏛️","image":"gaocheng.jpg","summary":"卫成公迁都帝丘，卫国都城凡388年所在地","intro":"高城遗址（卫国故城·帝丘）位于濮阳县五星乡高城村南金堤河南岸，是春秋战国时期卫国都城帝丘所在地。卫成公于公元前629年迁都帝丘，卫国都于此凡388年（前629—前241）。城址面积约916万平方米，是中原地区最大的东周城址之一，发现城垣、城壕、宫殿区、手工作坊区等遗迹。第七批全国重点文物保护单位（2013）。","archaeology":"第七批全国重点文物保护单位（2013）。2006年论证确认为东周卫国都城帝丘。","relics":[{"name":"东周城垣残段","desc":"高城遗址残存的东周城垣，是卫国城址形制研究的重要实物。"}],"events":[{"time":"前629年","title":"卫成公迁都帝丘","desc":"春秋卫成公迁都帝丘，卫国都于此凡388年。"}],"poems":[{"title":"卫都怀古","author":"宋代","content":"春秋卫都帝丘城，高城遗址在濮东。三百八十八年事，东周列国此留名。"}],"tourism":{"address":"濮阳县东南五星乡高城村南","openTime":"以景区公告为准","ticket":"以景区公告为准","tips":"可与戚城遗址、西水坡遗址联游。"},"keywords":["卫国都城","帝丘","东周","春秋","战国"]}'),
('huilanbei', '回銮碑', '濮阳', '宋', '古建筑', '北宋澶渊之盟实物碑刻', '北宋景德元年（1004）', '宋真宗澶渊之盟后所立，澶渊之盟唯一实物见证', 'huilanbei.jpg', '{"id":"huilanbei","name":"回銮碑","city":"濮阳","era":"宋","type":"古建筑","typeDesc":"北宋澶渊之盟实物碑刻","dynasty":"北宋景德元年（1004）","cover":"📜","image":"huilanbei.jpg","summary":"宋真宗澶渊之盟后所立，澶渊之盟唯一实物见证","intro":"回銮碑（亦称「契丹出境碑」）位于濮阳县御井街，是北宋景德元年（1004）澶渊之盟后，宋真宗班师回朝时所立。碑文为宋真宗御制《契丹出境》诗，记述了他亲征澶州、与辽订立「澶渊之盟」的经过。碑旁有「御井」，传为真宗驻跸澶州时所用。第八批全国重点文物保护单位（2019），是「澶渊之盟」这一重大历史事件的唯一实物见证。","archaeology":"第八批全国重点文物保护单位（2019）。","relics":[{"name":"宋真宗御制碑文","desc":"回銮碑碑文为宋真宗亲撰，是研究北宋辽金关系的珍贵史料。"}],"events":[{"time":"1004年","title":"澶渊之盟","desc":"北宋景德元年（1004）宋真宗与辽订立「澶渊之盟」，维持百年和平。"}],"poems":[{"title":"回銮碑","author":"宋真宗","content":"我为君诗碑上刻，君臣将士共安边。（《契丹出境》诗节录）"}],"tourism":{"address":"濮阳县御井街","openTime":"以景区公告为准","ticket":"以景区公告为准","tips":"可与戚城遗址、西水坡遗址联游。"},"keywords":["澶渊之盟","宋真宗","北宋辽金关系"]}')
